# D48 · 빔 탐색과 핫워드 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d48_decode.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
#   탐욕 탐색 → 빔 탐색 → 핫워드 가산 점수를 바꿔 가며 잰다
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import math, re
from collections import Counter


SR = 4000                                                # 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
N = 2000
PLACES = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"]
HAZARDS = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"]
GLOSSARY = PLACES + HAZARDS                              # 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
PHRASE = {"추락": "작업자가 추락했습니다", "화재": "화재가 발생했습니다", "누출": "가스가 누출되고 있습니다", "감전": "작업자가 감전됐습니다",
          "끼였": "손이 끼였습니다", "붕괴": "벽이 붕괴됐습니다", "연기": "연기가 나고 있습니다"}
CONF = {"추락": "주락", "화재": "화제", "누출": "노출", "감전": "반전", "끼였": "끼었", "붕괴": "봉괴", "연기": "연귀",          # 받아쓰기가 자주 헷갈리는 모양
        "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", "옥상냉각탑": "옥상냉각답",
        "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", "정문주차장": "정문주자장", "2층용접장": "이층용접장"}
KINDS = ["공장", "건설", "경보"]
SNRS = [5, 10, 15]
BASELINE = {"pre": None, "method": "greedy_search", "hotwords": [], "hot_score": 2.0, "paths": 4, "post": None}


def rnd(a, b=0):
    """같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)."""
    h = (a * 2654435761 + b * 40503 + 12345) & 0xFFFFFFFF
    h = (h ^ (h >> 15)) & 0xFFFFFFFF
    h = (h * 2246822519) & 0xFFFFFFFF
    h = (h ^ (h >> 13)) & 0xFFFFFFFF
    return h / 4294967296


# ---------- 지표 ----------
def clean(s):
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


def cer(ref, hyp):
    """글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다."""
    r, h = clean(ref), clean(hyp)
    d = list(range(len(h) + 1))
    for i, a in enumerate(r, 1):
        prev, d[0] = d[0], i
        for j, b in enumerate(h, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (a != b))
    return d[-1] / max(1, len(r))


def keyword_recall(keywords, hyp):
    """안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수."""
    h = re.sub(r"\s", "", hyp)
    return sum(k in h for k in keywords), len(keywords)


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def safety_score(c, recall):
    """대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다."""
    return round_half_up(100 * (0.5 * (1 - min(c, 1.0)) + 0.5 * recall), 1)


def grade(items, hyps):
    """발화별 채점표와 전체 점수."""
    rows, found, total = [], 0, 0
    for it, h in zip(items, hyps):
        f, n = keyword_recall(it["kw"], h)
        found += f
        total += n
        rows.append({"id": it["id"], "noise": it["kind"], "snr": it["snr"], "cer": cer(it["text"], h), "found": f, "kw": n, "hyp": h})
    c = sum(r["cer"] for r in rows) / len(rows)
    rec = found / max(1, total)
    return {"score": safety_score(c, rec), "cer": c, "recall": rec, "rows": rows}


# ---------- 한글 자모 거리 ----------
def jamo(s):
    """한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로."""
    out = []
    for ch in s:
        o = ord(ch) - 0xAC00
        if 0 <= o < 11172:
            out += [("초", o // 588), ("중", (o % 588) // 28), ("종", o % 28)]
        else:
            out.append(ch)
    return out


def jamo_len(s):
    return len(jamo(s))


def jamo_dist(a, b):
    """두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1."""
    a, b = jamo(a), jamo(b)
    d = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        prev, d[0] = d[0], i
        for j, y in enumerate(b, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (x != y))
    return d[-1]


def heard_as(keyword, hyp):
    """놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것."""
    t = clean(hyp)
    n = len(keyword)
    if len(t) < n:
        return t
    return min((t[s:s + n] for s in range(len(t) - n + 1)), key=lambda seg: jamo_dist(keyword, seg))


# ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
def tone_hz(k):
    return 300 + 30 * k


def make_text(k):
    place, hazard = PLACES[k % 10], HAZARDS[(k * 3 + k // 7) % 7]
    return f"{place}에서 {PHRASE[hazard]}", [place, hazard]


def make_noise(kind, n):
    nz = []
    for i in range(n):
        w = (rnd(7, i) * 2 - 1) * math.sqrt(3)           # 평균 0 · 힘 1인 잡음
        if kind == "공장":                                # 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
            hum = sum(a * math.sin(2 * math.pi * f * i / SR + p) for f, a, p in [(50, 1.0, 0.3), (100, 0.7, 1.7), (150, 0.5, 4.1)])
            nz.append(hum + 0.5 * w)
        elif kind == "건설":                              # 망치 소리(짧고 센 넓은 잡음) + 엔진
            nz.append(3 * w * math.exp(-(i % 1320) / 48) + 0.3 * w)
        else:                                            # 경보: 두 음을 오가는 경보음 + 배경
            nz.append(math.sin(2 * math.pi * (800 if (i // 500) % 2 == 0 else 1100) * i / SR) + 0.4 * w)
    return nz


def make_item(k):
    """발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean"""
    text, kw = make_text(k)
    kind, snr = KINDS[k % 3], SNRS[(k // 3) % 3]
    f = tone_hz(k)
    clean_y = [0.5 * math.sin(2 * math.pi * f * i / SR) + 0.3 * math.sin(2 * math.pi * 250 * i / SR) for i in range(N)]   # 목소리 = 높이 f + 기본음 250 Hz
    nz = make_noise(kind, N)
    p_s = sum(v * v for v in clean_y) / N
    g = math.sqrt(p_s / (10 ** (snr / 10) * sum(v * v for v in nz) / N))
    return {"id": f"S{k + 1:02d}", "k": k, "text": text, "kw": kw, "kind": kind, "snr": snr, "clean": clean_y, "y": [a + g * b for a, b in zip(clean_y, nz)]}


def make_items(ks):
    return [make_item(k) for k in ks]


# ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
def highpass(y, cutoff):
    """cutoff(Hz)보다 낮은 소리를 줄인 소리."""
    out = list(y)
    w0 = 2 * math.pi * cutoff / SR
    for q in (0.5412, 1.3066):
        al = math.sin(w0) / (2 * q)
        a0, a1, a2 = 1 + al, -2 * math.cos(w0), 1 - al
        b0 = (1 + math.cos(w0)) / 2
        b1 = -(1 + math.cos(w0))
        x1 = x2 = y1 = y2 = 0.0
        for i, x in enumerate(out):
            v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0
            x2, x1, y2, y1 = x1, x, y1, v
            out[i] = v
    return out


# ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
def amp_at(y, hz):
    """hz 성분의 크기 (괴츨 방법)"""
    c = 2 * math.cos(2 * math.pi * hz / SR)
    s1 = s2 = 0.0
    for v in y:
        s1, s2 = v + c * s1 - s2, s1
    return math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2 / len(y)


def listen(y, method="greedy_search", hotwords=(), hot_score=2.0, paths=4):
    amps = [amp_at(y, tone_hz(k)) for k in range(50)]
    k = amps.index(max(amps))
    a_p = amp_at(y, 250)
    speech = (amps[k] ** 2 + a_p ** 2) / 2
    noise = max(sum(v * v for v in y) / len(y) - speech, 1e-4)
    clarity = speech / noise * min(1.0, (a_p / amps[k]) / 0.6) ** 2     # 기본음이 잘려 나가면 또렷함이 크게 준다
    p = 1.0 / (1 + 0.08 * clarity)
    if method == "modified_beam_search":
        p *= 0.85 if paths >= 4 else 0.92                 # 후보 문장을 여럿 들고 가면 덜 틀린다
    text, kw = make_text(k)
    for j, w in enumerate(kw):
        pw = p / (1 + 0.8 * hot_score) if w in hotwords else p
        if rnd(k, 10 + j) < pw:
            text = text.replace(w, CONF[w])
    text = "".join("가" if "가" <= ch <= "힣" and rnd(k, 100 + i) < p * 0.2 else ch for i, ch in enumerate(text))
    if hotwords and rnd(k, 50) < 0.03 * hot_score ** 2:  # 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
        text = text.rsplit(" ", 1)[0] + " " + hotwords[k % len(hotwords)]
    return text


def run_system(system, ys):
    """시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다."""
    S = {**BASELINE, **(system or {})}
    skipped = set()
    if S["hotwords"] and S["method"] != "modified_beam_search":
        print("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.")
        S["hotwords"] = []
    if S["pre"]:
        out = []
        for y in ys:
            try:
                z = S["pre"](y)
                ok = isinstance(z, list) and len(z) == len(y) and all(math.isfinite(v) for v in z)
            except Exception:
                ok = False
            if not ok:
                skipped.add("전처리")
            out.append(z if ok else y)
        ys = out
    hyps = [listen(y, S["method"], S["hotwords"], S["hot_score"], S["paths"]) for y in ys]
    if S["post"]:
        out = []
        for h in hyps:
            try:
                z = S["post"](h)
                ok = isinstance(z, str)
            except Exception:
                ok = False
            if not ok:
                skipped.add("후처리")
            out.append(z if ok else h)
        hyps = out
    if skipped:
        print(f"[주의] {' · '.join(sorted(skipped))} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.")
    return hyps


def apply_dict(text, table):
    for wrong, right in table.items():
        text = text.replace(wrong, right)
    return text


def fuzzy_fix(text, lexicon, ratio):
    """용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다."""
    text = text.replace(" ", "")
    for word in lexicon:
        n = len(word)
        if word in text or len(text) < n:
            continue
        best = min(range(len(text) - n + 1), key=lambda s: jamo_dist(word, text[s:s + n]))
        if jamo_dist(word, text[best:best + n]) <= ratio * jamo_len(word):
            text = text[:best] + word + text[best + n:]
    return text


DEV = make_items(range(20))
YS = [x["y"] for x in DEV]
HOT = HAZARDS + ["창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"]   # 핫워드: 나오면 점수를 더 줄 낱말들

trials = [("탐욕 탐색 (기준선)", {"method": "greedy_search"}),
          ("빔 탐색 (후보 4개)", {"method": "modified_beam_search", "paths": 4}),                             # 후보 문장을 4개씩 들고 간다
          ("빔 + 핫워드 · 가산 1.0", {"method": "modified_beam_search", "hotwords": HOT, "hot_score": 1.0}),   # 핫워드의 토큰마다 점수를 더한다
          ("빔 + 핫워드 · 가산 2.0", {"method": "modified_beam_search", "hotwords": HOT, "hot_score": 2.0}),
          ("빔 + 핫워드 · 가산 4.0", {"method": "modified_beam_search", "hotwords": HOT, "hot_score": 4.0})]
DEC, HYPS = [], []
for label, system in trials:
    hyps = run_system(system, YS)
    g = grade(DEV, hyps)
    HYPS.append(hyps)
    DEC.append({"label": label, "score": g["score"], "cer": round(g["cer"] * 100, 1), "recall": round(g["recall"] * 100, 1)})
    print(f"{label} · 점수 {g['score']} · CER {DEC[-1]['cer']}% · 키워드 재현율 {DEC[-1]['recall']}%")

# 핫워드로 키워드를 더 찾은 발화 하나
for it, a, b in zip(DEV, HYPS[0], HYPS[3]):
    if keyword_recall(it["kw"], a)[0] < keyword_recall(it["kw"], b)[0]:
        print(f"   {it['id']}  {a}\n     →  {b}")
        break

# 핫워드는 빔 탐색에서만 듣는다: 탐욕 탐색에 주면 무시하고 기준선과 같은 글을 돌려준다
ignored = run_system({"method": "greedy_search", "hotwords": HOT}, YS) == HYPS[0]

check(len(DEC) == 5 and max(r["score"] for r in DEC[2:]) > DEC[0]["score"] and DEC[1]["score"] > DEC[0]["score"]
      and DEC[4]["score"] < max(DEC[2]["score"], DEC[3]["score"]) and DEC[4]["cer"] > DEC[2]["cer"] and ignored,
      "빔 탐색과 핫워드가 기준선보다 높고, 가산 점수를 너무 키우면(4.0) CER이 늘어 다시 떨어지며, 탐욕 탐색에서는 핫워드가 무시되어야 해요.")

decode.typescript:
// D48 · 빔 탐색과 핫워드 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d48_decode.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
//   탐욕 탐색 → 빔 탐색 → 핫워드 가산 점수를 바꿔 가며 잰다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

function same(a: unknown, b: unknown): boolean {
  // 값이 같은지(리스트 · 객체 포함) 비교
  return JSON.stringify(a) === JSON.stringify(b);
}

const SR = 4000; // 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
const N = 2000;
const PLACES: string[] = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"];
const HAZARDS: string[] = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"];
const GLOSSARY: string[] = [...PLACES, ...HAZARDS]; // 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
const PHRASE: Record<string, string> = {
  추락: "작업자가 추락했습니다", 화재: "화재가 발생했습니다", 누출: "가스가 누출되고 있습니다", 감전: "작업자가 감전됐습니다",
  끼였: "손이 끼였습니다", 붕괴: "벽이 붕괴됐습니다", 연기: "연기가 나고 있습니다",
};
const CONF: Record<string, string> = { // 받아쓰기가 자주 헷갈리는 모양
  추락: "주락", 화재: "화제", 누출: "노출", 감전: "반전", 끼였: "끼었", 붕괴: "봉괴", 연기: "연귀",
  "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", 옥상냉각탑: "옥상냉각답",
  "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", 정문주차장: "정문주자장", "2층용접장": "이층용접장",
};
const KINDS: string[] = ["공장", "건설", "경보"];
const SNRS: number[] = [5, 10, 15];

type Item = { id: string; k: number; text: string; kw: string[]; kind: string; snr: number; clean: number[]; y: number[] };
type System = { pre?: ((y: number[]) => any) | null; method?: string; hotwords?: string[]; hot_score?: number; paths?: number; post?: ((h: string) => any) | null };
type Row = { id: string; noise: string; snr: number; cer: number; found: number; kw: number; hyp: string };
type Grade = { score: number; cer: number; recall: number; rows: Row[] };
const BASELINE: Required<System> = { pre: null, method: "greedy_search", hotwords: [], hot_score: 2.0, paths: 4, post: null };

function rnd(a: number, b: number = 0): number {
  // 같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)
  let h = (a * 2654435761 + b * 40503 + 12345) % 4294967296;
  h = (h ^ (h >>> 15)) >>> 0;
  h = Math.imul(h, 2246822519) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  return h / 4294967296;
}

// ---------- 지표 ----------
function clean(s: string): string {
  return s.replace(/[^0-9A-Za-z가-힣]/g, "");
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다
  const r = [...clean(ref)], h = [...clean(hyp)];
  const d: number[] = Array.from({ length: h.length + 1 }, (_, i) => i);
  r.forEach((a, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    h.forEach((b, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (a !== b ? 1 : 0));
      prev = t;
    });
  });
  return d[h.length] / Math.max(1, r.length);
}

function keywordRecall(keywords: string[], hyp: string): [number, number] {
  // 안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수
  const h = hyp.replace(/\s/g, "");
  return [keywords.filter((k) => h.includes(k)).length, keywords.length];
}

function safetyScore(c: number, recall: number): number {
  // 대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다
  return roundHalfUp(100 * (0.5 * (1 - Math.min(c, 1.0)) + 0.5 * recall), 1);
}

function grade(items: Item[], hyps: string[]): Grade {
  // 발화별 채점표와 전체 점수
  const rows: Row[] = [];
  let found = 0, total = 0;
  items.forEach((it, i) => {
    const [f, n] = keywordRecall(it.kw, hyps[i]);
    found += f;
    total += n;
    rows.push({ id: it.id, noise: it.kind, snr: it.snr, cer: cer(it.text, hyps[i]), found: f, kw: n, hyp: hyps[i] });
  });
  const c = rows.reduce((s, r) => s + r.cer, 0) / rows.length;
  const rec = found / Math.max(1, total);
  return { score: safetyScore(c, rec), cer: c, recall: rec, rows };
}

// ---------- 한글 자모 거리 ----------
function jamo(s: string): string[] {
  // 한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로
  const out: string[] = [];
  for (const ch of s) {
    const o = ch.charCodeAt(0) - 0xac00;
    if (o >= 0 && o < 11172) out.push("초" + Math.floor(o / 588), "중" + Math.floor((o % 588) / 28), "종" + (o % 28));
    else out.push(ch);
  }
  return out;
}

function jamoLen(s: string): number {
  return jamo(s).length;
}

function jamoDist(a0: string, b0: string): number {
  // 두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1
  const a = jamo(a0), b = jamo(b0);
  const d: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
  a.forEach((x, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    b.forEach((y, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (x !== y ? 1 : 0));
      prev = t;
    });
  });
  return d[b.length];
}

function argmin<T>(xs: T[], key: (x: T) => number): number {
  // 가장 작은 값의 번호 (같으면 앞의 것)
  let best = 0;
  xs.forEach((x, i) => { if (key(x) < key(xs[best])) best = i; });
  return best;
}

function heardAs(keyword: string, hyp: string): string {
  // 놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것
  const t = clean(hyp), n = keyword.length;
  if (t.length < n) return t;
  const segs: string[] = [];
  for (let s = 0; s <= t.length - n; s++) segs.push(t.slice(s, s + n));
  return segs[argmin(segs, (seg) => jamoDist(keyword, seg))];
}

// ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
function toneHz(k: number): number {
  return 300 + 30 * k;
}

function makeText(k: number): [string, string[]] {
  const place = PLACES[k % 10], hazard = HAZARDS[(k * 3 + Math.floor(k / 7)) % 7];
  return [`${place}에서 ${PHRASE[hazard]}`, [place, hazard]];
}

function makeNoise(kind: string, n: number): number[] {
  const nz: number[] = [];
  for (let i = 0; i < n; i++) {
    const w = (rnd(7, i) * 2 - 1) * Math.sqrt(3); // 평균 0 · 힘 1인 잡음
    if (kind === "공장") { // 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
      let hum = 0;
      for (const [f, a, p] of [[50, 1.0, 0.3], [100, 0.7, 1.7], [150, 0.5, 4.1]]) hum += a * Math.sin((2 * Math.PI * f * i) / SR + p);
      nz.push(hum + 0.5 * w);
    } else if (kind === "건설") { // 망치 소리(짧고 센 넓은 잡음) + 엔진
      nz.push(3 * w * Math.exp(-(i % 1320) / 48) + 0.3 * w);
    } else { // 경보: 두 음을 오가는 경보음 + 배경
      nz.push(Math.sin((2 * Math.PI * (Math.floor(i / 500) % 2 === 0 ? 800 : 1100) * i) / SR) + 0.4 * w);
    }
  }
  return nz;
}

function makeItem(k: number): Item {
  // 발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean
  const [text, kw] = makeText(k);
  const kind = KINDS[k % 3], snr = SNRS[Math.floor(k / 3) % 3];
  const f = toneHz(k);
  const cleanY = Array.from({ length: N }, (_, i) => 0.5 * Math.sin((2 * Math.PI * f * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 250 * i) / SR)); // 목소리 = 높이 f + 기본음 250 Hz
  const nz = makeNoise(kind, N);
  const pS = cleanY.reduce((s, v) => s + v * v, 0) / N;
  const g = Math.sqrt(pS / (10 ** (snr / 10) * (nz.reduce((s, v) => s + v * v, 0) / N)));
  return { id: `S${String(k + 1).padStart(2, "0")}`, k, text, kw, kind, snr, clean: cleanY, y: cleanY.map((a, i) => a + g * nz[i]) };
}

function makeItems(ks: number[]): Item[] {
  return ks.map(makeItem);
}

function range(a: number, b: number): number[] {
  return Array.from({ length: b - a }, (_, i) => a + i);
}

// ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
function highpass(y: number[], cutoff: number): number[] {
  // cutoff(Hz)보다 낮은 소리를 줄인 소리
  const out = [...y];
  const w0 = (2 * Math.PI * cutoff) / SR;
  for (const q of [0.5412, 1.3066]) {
    const al = Math.sin(w0) / (2 * q);
    const a0 = 1 + al, a1 = -2 * Math.cos(w0), a2 = 1 - al;
    const b0 = (1 + Math.cos(w0)) / 2, b1 = -(1 + Math.cos(w0));
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let i = 0; i < out.length; i++) {
      const x = out[i];
      const v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0;
      x2 = x1; x1 = x; y2 = y1; y1 = v;
      out[i] = v;
    }
  }
  return out;
}

// ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
function ampAt(y: number[], hz: number): number {
  // hz 성분의 크기 (괴츨 방법)
  const c = 2 * Math.cos((2 * Math.PI * hz) / SR);
  let s1 = 0, s2 = 0;
  for (const v of y) {
    const s0 = v + c * s1 - s2;
    s2 = s1;
    s1 = s0;
  }
  return (Math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2) / y.length;
}

function listen(y: number[], method: string = "greedy_search", hotwords: string[] = [], hotScore: number = 2.0, paths: number = 4): string {
  const amps = range(0, 50).map((k) => ampAt(y, toneHz(k)));
  const k = amps.indexOf(Math.max(...amps));
  const aP = ampAt(y, 250);
  const speech = (amps[k] ** 2 + aP ** 2) / 2;
  const noise = Math.max(y.reduce((s, v) => s + v * v, 0) / y.length - speech, 1e-4);
  const clarity = (speech / noise) * Math.min(1.0, aP / amps[k] / 0.6) ** 2; // 기본음이 잘려 나가면 또렷함이 크게 준다
  let p = 1.0 / (1 + 0.08 * clarity);
  if (method === "modified_beam_search") p *= paths >= 4 ? 0.85 : 0.92; // 후보 문장을 여럿 들고 가면 덜 틀린다
  let [text, kw] = makeText(k);
  kw.forEach((w, j) => {
    const pw = hotwords.includes(w) ? p / (1 + 0.8 * hotScore) : p;
    if (rnd(k, 10 + j) < pw) text = text.replaceAll(w, CONF[w]);
  });
  text = [...text].map((ch, i) => (ch >= "가" && ch <= "힣" && rnd(k, 100 + i) < p * 0.2 ? "가" : ch)).join("");
  if (hotwords.length > 0 && rnd(k, 50) < 0.03 * hotScore ** 2) { // 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
    text = text.slice(0, text.lastIndexOf(" ")) + " " + hotwords[k % hotwords.length];
  }
  return text;
}

function runSystem(system: System | null, ys: number[][]): string[] {
  // 시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다
  const S = { ...BASELINE, ...(system ?? {}) };
  const skipped = new Set<string>();
  if (S.hotwords.length > 0 && S.method !== "modified_beam_search") {
    console.log("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.");
    S.hotwords = [];
  }
  if (S.pre) {
    ys = ys.map((y) => {
      let z: any, ok: boolean;
      try {
        z = S.pre!(y);
        ok = Array.isArray(z) && z.length === y.length && z.every((v: number) => Number.isFinite(v));
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("전처리");
      return ok ? z : y;
    });
  }
  let hyps = ys.map((y) => listen(y, S.method, S.hotwords, S.hot_score, S.paths));
  if (S.post) {
    hyps = hyps.map((h) => {
      let z: any, ok: boolean;
      try {
        z = S.post!(h);
        ok = typeof z === "string";
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("후처리");
      return ok ? z : h;
    });
  }
  if (skipped.size > 0) console.log(`[주의] ${[...skipped].sort().join(" · ")} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.`);
  return hyps;
}

function applyDict(text: string, table: Record<string, string>): string {
  for (const [wrong, right] of Object.entries(table)) text = text.replaceAll(wrong, right);
  return text;
}

function fuzzyFix(text: string, lexicon: string[], ratio: number): string {
  // 용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다
  text = text.replaceAll(" ", "");
  for (const word of lexicon) {
    const n = word.length;
    if (text.includes(word) || text.length < n) continue;
    const starts = range(0, text.length - n + 1);
    const best = starts[argmin(starts, (s) => jamoDist(word, text.slice(s, s + n)))];
    if (jamoDist(word, text.slice(best, best + n)) <= ratio * jamoLen(word)) text = text.slice(0, best) + word + text.slice(best + n);
  }
  return text;
}

const DEV = makeItems(range(0, 20));
const YS = DEV.map((x) => x.y);
const HOT: string[] = [...HAZARDS, "창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"]; // 핫워드: 나오면 점수를 더 줄 낱말들

const trials: [string, System][] = [
  ["탐욕 탐색 (기준선)", { method: "greedy_search" }],
  ["빔 탐색 (후보 4개)", { method: "modified_beam_search", paths: 4 }], // 후보 문장을 4개씩 들고 간다
  ["빔 + 핫워드 · 가산 1.0", { method: "modified_beam_search", hotwords: HOT, hot_score: 1.0 }], // 핫워드의 토큰마다 점수를 더한다
  ["빔 + 핫워드 · 가산 2.0", { method: "modified_beam_search", hotwords: HOT, hot_score: 2.0 }],
  ["빔 + 핫워드 · 가산 4.0", { method: "modified_beam_search", hotwords: HOT, hot_score: 4.0 }],
];
const DEC: { label: string; score: number; cer: number; recall: number }[] = [];
const HYPS: string[][] = [];
for (const [label, system] of trials) {
  const hyps = runSystem(system, YS);
  const g = grade(DEV, hyps);
  HYPS.push(hyps);
  DEC.push({ label, score: g.score, cer: Math.round(g.cer * 1000) / 10, recall: Math.round(g.recall * 1000) / 10 });
  console.log(`${label} · 점수 ${g.score} · CER ${DEC[DEC.length - 1].cer}% · 키워드 재현율 ${DEC[DEC.length - 1].recall}%`);
}

// 핫워드로 키워드를 더 찾은 발화 하나
for (let i = 0; i < DEV.length; i++) {
  if (keywordRecall(DEV[i].kw, HYPS[0][i])[0] < keywordRecall(DEV[i].kw, HYPS[3][i])[0]) {
    console.log(`   ${DEV[i].id}  ${HYPS[0][i]}\n     →  ${HYPS[3][i]}`);
    break;
  }
}

// 핫워드는 빔 탐색에서만 듣는다: 탐욕 탐색에 주면 무시하고 기준선과 같은 글을 돌려준다
const ignored = same(runSystem({ method: "greedy_search", hotwords: HOT }, YS), HYPS[0]);

check(
  DEC.length === 5 && Math.max(...DEC.slice(2).map((r) => r.score)) > DEC[0].score && DEC[1].score > DEC[0].score &&
    DEC[4].score < Math.max(DEC[2].score, DEC[3].score) && DEC[4].cer > DEC[2].cer && ignored,
  "빔 탐색과 핫워드가 기준선보다 높고, 가산 점수를 너무 키우면(4.0) CER이 늘어 다시 떨어지며, 탐욕 탐색에서는 핫워드가 무시되어야 해요.",
);

fuzzy.typescript:
// D48 · 용어집에 맞춰 고치기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d48_fuzzy.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
//   치환 사전과 자모 거리 용어집 맞추기: 문턱이 너무 느슨하면 맞는 글까지 망가진다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

function same(a: unknown, b: unknown): boolean {
  // 값이 같은지(리스트 · 객체 포함) 비교
  return JSON.stringify(a) === JSON.stringify(b);
}

const SR = 4000; // 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
const N = 2000;
const PLACES: string[] = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"];
const HAZARDS: string[] = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"];
const GLOSSARY: string[] = [...PLACES, ...HAZARDS]; // 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
const PHRASE: Record<string, string> = {
  추락: "작업자가 추락했습니다", 화재: "화재가 발생했습니다", 누출: "가스가 누출되고 있습니다", 감전: "작업자가 감전됐습니다",
  끼였: "손이 끼였습니다", 붕괴: "벽이 붕괴됐습니다", 연기: "연기가 나고 있습니다",
};
const CONF: Record<string, string> = { // 받아쓰기가 자주 헷갈리는 모양
  추락: "주락", 화재: "화제", 누출: "노출", 감전: "반전", 끼였: "끼었", 붕괴: "봉괴", 연기: "연귀",
  "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", 옥상냉각탑: "옥상냉각답",
  "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", 정문주차장: "정문주자장", "2층용접장": "이층용접장",
};
const KINDS: string[] = ["공장", "건설", "경보"];
const SNRS: number[] = [5, 10, 15];

type Item = { id: string; k: number; text: string; kw: string[]; kind: string; snr: number; clean: number[]; y: number[] };
type System = { pre?: ((y: number[]) => any) | null; method?: string; hotwords?: string[]; hot_score?: number; paths?: number; post?: ((h: string) => any) | null };
type Row = { id: string; noise: string; snr: number; cer: number; found: number; kw: number; hyp: string };
type Grade = { score: number; cer: number; recall: number; rows: Row[] };
const BASELINE: Required<System> = { pre: null, method: "greedy_search", hotwords: [], hot_score: 2.0, paths: 4, post: null };

function rnd(a: number, b: number = 0): number {
  // 같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)
  let h = (a * 2654435761 + b * 40503 + 12345) % 4294967296;
  h = (h ^ (h >>> 15)) >>> 0;
  h = Math.imul(h, 2246822519) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  return h / 4294967296;
}

// ---------- 지표 ----------
function clean(s: string): string {
  return s.replace(/[^0-9A-Za-z가-힣]/g, "");
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다
  const r = [...clean(ref)], h = [...clean(hyp)];
  const d: number[] = Array.from({ length: h.length + 1 }, (_, i) => i);
  r.forEach((a, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    h.forEach((b, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (a !== b ? 1 : 0));
      prev = t;
    });
  });
  return d[h.length] / Math.max(1, r.length);
}

function keywordRecall(keywords: string[], hyp: string): [number, number] {
  // 안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수
  const h = hyp.replace(/\s/g, "");
  return [keywords.filter((k) => h.includes(k)).length, keywords.length];
}

function safetyScore(c: number, recall: number): number {
  // 대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다
  return roundHalfUp(100 * (0.5 * (1 - Math.min(c, 1.0)) + 0.5 * recall), 1);
}

function grade(items: Item[], hyps: string[]): Grade {
  // 발화별 채점표와 전체 점수
  const rows: Row[] = [];
  let found = 0, total = 0;
  items.forEach((it, i) => {
    const [f, n] = keywordRecall(it.kw, hyps[i]);
    found += f;
    total += n;
    rows.push({ id: it.id, noise: it.kind, snr: it.snr, cer: cer(it.text, hyps[i]), found: f, kw: n, hyp: hyps[i] });
  });
  const c = rows.reduce((s, r) => s + r.cer, 0) / rows.length;
  const rec = found / Math.max(1, total);
  return { score: safetyScore(c, rec), cer: c, recall: rec, rows };
}

// ---------- 한글 자모 거리 ----------
function jamo(s: string): string[] {
  // 한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로
  const out: string[] = [];
  for (const ch of s) {
    const o = ch.charCodeAt(0) - 0xac00;
    if (o >= 0 && o < 11172) out.push("초" + Math.floor(o / 588), "중" + Math.floor((o % 588) / 28), "종" + (o % 28));
    else out.push(ch);
  }
  return out;
}

function jamoLen(s: string): number {
  return jamo(s).length;
}

function jamoDist(a0: string, b0: string): number {
  // 두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1
  const a = jamo(a0), b = jamo(b0);
  const d: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
  a.forEach((x, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    b.forEach((y, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (x !== y ? 1 : 0));
      prev = t;
    });
  });
  return d[b.length];
}

function argmin<T>(xs: T[], key: (x: T) => number): number {
  // 가장 작은 값의 번호 (같으면 앞의 것)
  let best = 0;
  xs.forEach((x, i) => { if (key(x) < key(xs[best])) best = i; });
  return best;
}

function heardAs(keyword: string, hyp: string): string {
  // 놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것
  const t = clean(hyp), n = keyword.length;
  if (t.length < n) return t;
  const segs: string[] = [];
  for (let s = 0; s <= t.length - n; s++) segs.push(t.slice(s, s + n));
  return segs[argmin(segs, (seg) => jamoDist(keyword, seg))];
}

// ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
function toneHz(k: number): number {
  return 300 + 30 * k;
}

function makeText(k: number): [string, string[]] {
  const place = PLACES[k % 10], hazard = HAZARDS[(k * 3 + Math.floor(k / 7)) % 7];
  return [`${place}에서 ${PHRASE[hazard]}`, [place, hazard]];
}

function makeNoise(kind: string, n: number): number[] {
  const nz: number[] = [];
  for (let i = 0; i < n; i++) {
    const w = (rnd(7, i) * 2 - 1) * Math.sqrt(3); // 평균 0 · 힘 1인 잡음
    if (kind === "공장") { // 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
      let hum = 0;
      for (const [f, a, p] of [[50, 1.0, 0.3], [100, 0.7, 1.7], [150, 0.5, 4.1]]) hum += a * Math.sin((2 * Math.PI * f * i) / SR + p);
      nz.push(hum + 0.5 * w);
    } else if (kind === "건설") { // 망치 소리(짧고 센 넓은 잡음) + 엔진
      nz.push(3 * w * Math.exp(-(i % 1320) / 48) + 0.3 * w);
    } else { // 경보: 두 음을 오가는 경보음 + 배경
      nz.push(Math.sin((2 * Math.PI * (Math.floor(i / 500) % 2 === 0 ? 800 : 1100) * i) / SR) + 0.4 * w);
    }
  }
  return nz;
}

function makeItem(k: number): Item {
  // 발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean
  const [text, kw] = makeText(k);
  const kind = KINDS[k % 3], snr = SNRS[Math.floor(k / 3) % 3];
  const f = toneHz(k);
  const cleanY = Array.from({ length: N }, (_, i) => 0.5 * Math.sin((2 * Math.PI * f * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 250 * i) / SR)); // 목소리 = 높이 f + 기본음 250 Hz
  const nz = makeNoise(kind, N);
  const pS = cleanY.reduce((s, v) => s + v * v, 0) / N;
  const g = Math.sqrt(pS / (10 ** (snr / 10) * (nz.reduce((s, v) => s + v * v, 0) / N)));
  return { id: `S${String(k + 1).padStart(2, "0")}`, k, text, kw, kind, snr, clean: cleanY, y: cleanY.map((a, i) => a + g * nz[i]) };
}

function makeItems(ks: number[]): Item[] {
  return ks.map(makeItem);
}

function range(a: number, b: number): number[] {
  return Array.from({ length: b - a }, (_, i) => a + i);
}

// ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
function highpass(y: number[], cutoff: number): number[] {
  // cutoff(Hz)보다 낮은 소리를 줄인 소리
  const out = [...y];
  const w0 = (2 * Math.PI * cutoff) / SR;
  for (const q of [0.5412, 1.3066]) {
    const al = Math.sin(w0) / (2 * q);
    const a0 = 1 + al, a1 = -2 * Math.cos(w0), a2 = 1 - al;
    const b0 = (1 + Math.cos(w0)) / 2, b1 = -(1 + Math.cos(w0));
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let i = 0; i < out.length; i++) {
      const x = out[i];
      const v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0;
      x2 = x1; x1 = x; y2 = y1; y1 = v;
      out[i] = v;
    }
  }
  return out;
}

// ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
function ampAt(y: number[], hz: number): number {
  // hz 성분의 크기 (괴츨 방법)
  const c = 2 * Math.cos((2 * Math.PI * hz) / SR);
  let s1 = 0, s2 = 0;
  for (const v of y) {
    const s0 = v + c * s1 - s2;
    s2 = s1;
    s1 = s0;
  }
  return (Math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2) / y.length;
}

function listen(y: number[], method: string = "greedy_search", hotwords: string[] = [], hotScore: number = 2.0, paths: number = 4): string {
  const amps = range(0, 50).map((k) => ampAt(y, toneHz(k)));
  const k = amps.indexOf(Math.max(...amps));
  const aP = ampAt(y, 250);
  const speech = (amps[k] ** 2 + aP ** 2) / 2;
  const noise = Math.max(y.reduce((s, v) => s + v * v, 0) / y.length - speech, 1e-4);
  const clarity = (speech / noise) * Math.min(1.0, aP / amps[k] / 0.6) ** 2; // 기본음이 잘려 나가면 또렷함이 크게 준다
  let p = 1.0 / (1 + 0.08 * clarity);
  if (method === "modified_beam_search") p *= paths >= 4 ? 0.85 : 0.92; // 후보 문장을 여럿 들고 가면 덜 틀린다
  let [text, kw] = makeText(k);
  kw.forEach((w, j) => {
    const pw = hotwords.includes(w) ? p / (1 + 0.8 * hotScore) : p;
    if (rnd(k, 10 + j) < pw) text = text.replaceAll(w, CONF[w]);
  });
  text = [...text].map((ch, i) => (ch >= "가" && ch <= "힣" && rnd(k, 100 + i) < p * 0.2 ? "가" : ch)).join("");
  if (hotwords.length > 0 && rnd(k, 50) < 0.03 * hotScore ** 2) { // 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
    text = text.slice(0, text.lastIndexOf(" ")) + " " + hotwords[k % hotwords.length];
  }
  return text;
}

function runSystem(system: System | null, ys: number[][]): string[] {
  // 시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다
  const S = { ...BASELINE, ...(system ?? {}) };
  const skipped = new Set<string>();
  if (S.hotwords.length > 0 && S.method !== "modified_beam_search") {
    console.log("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.");
    S.hotwords = [];
  }
  if (S.pre) {
    ys = ys.map((y) => {
      let z: any, ok: boolean;
      try {
        z = S.pre!(y);
        ok = Array.isArray(z) && z.length === y.length && z.every((v: number) => Number.isFinite(v));
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("전처리");
      return ok ? z : y;
    });
  }
  let hyps = ys.map((y) => listen(y, S.method, S.hotwords, S.hot_score, S.paths));
  if (S.post) {
    hyps = hyps.map((h) => {
      let z: any, ok: boolean;
      try {
        z = S.post!(h);
        ok = typeof z === "string";
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("후처리");
      return ok ? z : h;
    });
  }
  if (skipped.size > 0) console.log(`[주의] ${[...skipped].sort().join(" · ")} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.`);
  return hyps;
}

function applyDict(text: string, table: Record<string, string>): string {
  for (const [wrong, right] of Object.entries(table)) text = text.replaceAll(wrong, right);
  return text;
}

function fuzzyFix(text: string, lexicon: string[], ratio: number): string {
  // 용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다
  text = text.replaceAll(" ", "");
  for (const word of lexicon) {
    const n = word.length;
    if (text.includes(word) || text.length < n) continue;
    const starts = range(0, text.length - n + 1);
    const best = starts[argmin(starts, (s) => jamoDist(word, text.slice(s, s + n)))];
    if (jamoDist(word, text.slice(best, best + n)) <= ratio * jamoLen(word)) text = text.slice(0, best) + word + text.slice(best + n);
  }
  return text;
}

const DEV = makeItems(range(0, 20));
const YS = DEV.map((x) => x.y);
const BASE = grade(DEV, runSystem(null, YS));
const HYP0 = BASE.rows.map((r) => r.hyp); // 기준선이 받아쓴 글 20개 (다시 받아쓰지 않아 빠르다)

// ── 치환 사전 · 용어집 맞추기를 예시로 확인 ──
const T: Record<string, string> = { 화제: "화재", 노출: "누출" };
const okDict = same(
  [applyDict("2번창고에서화제가발생했습니다", T), applyDict("가스가노출되고화제도났습니다", T), applyDict("이상없습니다", T)],
  ["2번창고에서화재가발생했습니다", "가스가누출되고화재도났습니다", "이상없습니다"],
);
const okFuzzy = same(
  [fuzzyFix("1층하육장에서 연기가 나고 있습니다", ["1층하역장"], 0.34), fuzzyFix("법원라인에서 화제가 발생했습니다", ["5번라인", "화재"], 0.34),
    fuzzyFix("법원라인에서 화제가 발생했습니다", ["5번라인", "화재"], 0.45), fuzzyFix("3층비계에서 추락", ["3층비계", "추락"], 0.34),
    fuzzyFix("화제", ["지하1층기계실"], 0.34)],
  ["1층하역장에서연기가나고있습니다", "법원라인에서화재가발생했습니다", "5번라인에서화재가발생했습니다", "3층비계에서추락", "화제"],
);
console.log("치환 사전 예시:", okDict, "· 용어집 맞추기 예시:", okFuzzy);

// ── 후처리 실험: 문턱(ratio)을 바꿔 가며 잰다 ──
const POST: { label: string; score: number; cer: number; recall: number; changed: number }[] = [];

function tryPost(label: string, fn: (h: string) => string): void {
  const out = HYP0.map(fn);
  const g = grade(DEV, out);
  const changed = out.filter((a, i) => clean(a) !== clean(HYP0[i])).length; // 글이 바뀐 발화의 수
  POST.push({ label, score: g.score, cer: Math.round(g.cer * 1000) / 10, recall: Math.round(g.recall * 1000) / 10, changed });
  console.log(`${label} · 점수 ${g.score} · CER ${POST[POST.length - 1].cer}% · 키워드 재현율 ${POST[POST.length - 1].recall}% · 바뀐 발화 ${changed}`);
}

tryPost("없음 (기준선)", (h) => h);
tryPost("치환 사전 (2개)", (h) => applyDict(h, T));
for (const ratio of [0.15, 0.25, 0.34, 0.45, 0.6]) tryPost(`용어집 맞추기 · 문턱 ${ratio}`, (h) => fuzzyFix(h, GLOSSARY, ratio)); // 문턱이 클수록 더 많이 고친다

// 느슨한 문턱이 맞는 글을 망가뜨린 예 하나
for (const h of HYP0) {
  const a = fuzzyFix(h, GLOSSARY, 0.34), b = fuzzyFix(h, GLOSSARY, 0.6);
  if (a !== b) {
    console.log("문턱 0.34:", a);
    console.log("문턱 0.6 :", b);
    break;
  }
}

check(
  okDict && okFuzzy && POST.length === 7 && POST[4].score > POST[0].score + 5 && POST[6].score < POST[5].score &&
    POST[6].cer > POST[5].cer && POST[6].changed > POST[4].changed,
  "용어집 맞추기(문턱 0.34)가 기준선보다 5점 넘게 높고, 문턱 0.6은 0.45보다 낮아야 해요(너무 많이 고침).",
);

shake.python:
# D48 · 공개 점수와 비공개 점수 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d48_shake.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
#   숨은 평가 세트에 제출하고 마감해 비공개 점수를 연다
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import math, re
from collections import Counter


SR = 4000                                                # 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
N = 2000
PLACES = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"]
HAZARDS = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"]
GLOSSARY = PLACES + HAZARDS                              # 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
PHRASE = {"추락": "작업자가 추락했습니다", "화재": "화재가 발생했습니다", "누출": "가스가 누출되고 있습니다", "감전": "작업자가 감전됐습니다",
          "끼였": "손이 끼였습니다", "붕괴": "벽이 붕괴됐습니다", "연기": "연기가 나고 있습니다"}
CONF = {"추락": "주락", "화재": "화제", "누출": "노출", "감전": "반전", "끼였": "끼었", "붕괴": "봉괴", "연기": "연귀",          # 받아쓰기가 자주 헷갈리는 모양
        "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", "옥상냉각탑": "옥상냉각답",
        "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", "정문주차장": "정문주자장", "2층용접장": "이층용접장"}
KINDS = ["공장", "건설", "경보"]
SNRS = [5, 10, 15]
BASELINE = {"pre": None, "method": "greedy_search", "hotwords": [], "hot_score": 2.0, "paths": 4, "post": None}


def rnd(a, b=0):
    """같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)."""
    h = (a * 2654435761 + b * 40503 + 12345) & 0xFFFFFFFF
    h = (h ^ (h >> 15)) & 0xFFFFFFFF
    h = (h * 2246822519) & 0xFFFFFFFF
    h = (h ^ (h >> 13)) & 0xFFFFFFFF
    return h / 4294967296


# ---------- 지표 ----------
def clean(s):
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


def cer(ref, hyp):
    """글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다."""
    r, h = clean(ref), clean(hyp)
    d = list(range(len(h) + 1))
    for i, a in enumerate(r, 1):
        prev, d[0] = d[0], i
        for j, b in enumerate(h, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (a != b))
    return d[-1] / max(1, len(r))


def keyword_recall(keywords, hyp):
    """안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수."""
    h = re.sub(r"\s", "", hyp)
    return sum(k in h for k in keywords), len(keywords)


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def safety_score(c, recall):
    """대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다."""
    return round_half_up(100 * (0.5 * (1 - min(c, 1.0)) + 0.5 * recall), 1)


def grade(items, hyps):
    """발화별 채점표와 전체 점수."""
    rows, found, total = [], 0, 0
    for it, h in zip(items, hyps):
        f, n = keyword_recall(it["kw"], h)
        found += f
        total += n
        rows.append({"id": it["id"], "noise": it["kind"], "snr": it["snr"], "cer": cer(it["text"], h), "found": f, "kw": n, "hyp": h})
    c = sum(r["cer"] for r in rows) / len(rows)
    rec = found / max(1, total)
    return {"score": safety_score(c, rec), "cer": c, "recall": rec, "rows": rows}


# ---------- 한글 자모 거리 ----------
def jamo(s):
    """한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로."""
    out = []
    for ch in s:
        o = ord(ch) - 0xAC00
        if 0 <= o < 11172:
            out += [("초", o // 588), ("중", (o % 588) // 28), ("종", o % 28)]
        else:
            out.append(ch)
    return out


def jamo_len(s):
    return len(jamo(s))


def jamo_dist(a, b):
    """두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1."""
    a, b = jamo(a), jamo(b)
    d = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        prev, d[0] = d[0], i
        for j, y in enumerate(b, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (x != y))
    return d[-1]


def heard_as(keyword, hyp):
    """놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것."""
    t = clean(hyp)
    n = len(keyword)
    if len(t) < n:
        return t
    return min((t[s:s + n] for s in range(len(t) - n + 1)), key=lambda seg: jamo_dist(keyword, seg))


# ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
def tone_hz(k):
    return 300 + 30 * k


def make_text(k):
    place, hazard = PLACES[k % 10], HAZARDS[(k * 3 + k // 7) % 7]
    return f"{place}에서 {PHRASE[hazard]}", [place, hazard]


def make_noise(kind, n):
    nz = []
    for i in range(n):
        w = (rnd(7, i) * 2 - 1) * math.sqrt(3)           # 평균 0 · 힘 1인 잡음
        if kind == "공장":                                # 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
            hum = sum(a * math.sin(2 * math.pi * f * i / SR + p) for f, a, p in [(50, 1.0, 0.3), (100, 0.7, 1.7), (150, 0.5, 4.1)])
            nz.append(hum + 0.5 * w)
        elif kind == "건설":                              # 망치 소리(짧고 센 넓은 잡음) + 엔진
            nz.append(3 * w * math.exp(-(i % 1320) / 48) + 0.3 * w)
        else:                                            # 경보: 두 음을 오가는 경보음 + 배경
            nz.append(math.sin(2 * math.pi * (800 if (i // 500) % 2 == 0 else 1100) * i / SR) + 0.4 * w)
    return nz


def make_item(k):
    """발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean"""
    text, kw = make_text(k)
    kind, snr = KINDS[k % 3], SNRS[(k // 3) % 3]
    f = tone_hz(k)
    clean_y = [0.5 * math.sin(2 * math.pi * f * i / SR) + 0.3 * math.sin(2 * math.pi * 250 * i / SR) for i in range(N)]   # 목소리 = 높이 f + 기본음 250 Hz
    nz = make_noise(kind, N)
    p_s = sum(v * v for v in clean_y) / N
    g = math.sqrt(p_s / (10 ** (snr / 10) * sum(v * v for v in nz) / N))
    return {"id": f"S{k + 1:02d}", "k": k, "text": text, "kw": kw, "kind": kind, "snr": snr, "clean": clean_y, "y": [a + g * b for a, b in zip(clean_y, nz)]}


def make_items(ks):
    return [make_item(k) for k in ks]


# ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
def highpass(y, cutoff):
    """cutoff(Hz)보다 낮은 소리를 줄인 소리."""
    out = list(y)
    w0 = 2 * math.pi * cutoff / SR
    for q in (0.5412, 1.3066):
        al = math.sin(w0) / (2 * q)
        a0, a1, a2 = 1 + al, -2 * math.cos(w0), 1 - al
        b0 = (1 + math.cos(w0)) / 2
        b1 = -(1 + math.cos(w0))
        x1 = x2 = y1 = y2 = 0.0
        for i, x in enumerate(out):
            v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0
            x2, x1, y2, y1 = x1, x, y1, v
            out[i] = v
    return out


# ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
def amp_at(y, hz):
    """hz 성분의 크기 (괴츨 방법)"""
    c = 2 * math.cos(2 * math.pi * hz / SR)
    s1 = s2 = 0.0
    for v in y:
        s1, s2 = v + c * s1 - s2, s1
    return math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2 / len(y)


def listen(y, method="greedy_search", hotwords=(), hot_score=2.0, paths=4):
    amps = [amp_at(y, tone_hz(k)) for k in range(50)]
    k = amps.index(max(amps))
    a_p = amp_at(y, 250)
    speech = (amps[k] ** 2 + a_p ** 2) / 2
    noise = max(sum(v * v for v in y) / len(y) - speech, 1e-4)
    clarity = speech / noise * min(1.0, (a_p / amps[k]) / 0.6) ** 2     # 기본음이 잘려 나가면 또렷함이 크게 준다
    p = 1.0 / (1 + 0.08 * clarity)
    if method == "modified_beam_search":
        p *= 0.85 if paths >= 4 else 0.92                 # 후보 문장을 여럿 들고 가면 덜 틀린다
    text, kw = make_text(k)
    for j, w in enumerate(kw):
        pw = p / (1 + 0.8 * hot_score) if w in hotwords else p
        if rnd(k, 10 + j) < pw:
            text = text.replace(w, CONF[w])
    text = "".join("가" if "가" <= ch <= "힣" and rnd(k, 100 + i) < p * 0.2 else ch for i, ch in enumerate(text))
    if hotwords and rnd(k, 50) < 0.03 * hot_score ** 2:  # 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
        text = text.rsplit(" ", 1)[0] + " " + hotwords[k % len(hotwords)]
    return text


def run_system(system, ys):
    """시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다."""
    S = {**BASELINE, **(system or {})}
    skipped = set()
    if S["hotwords"] and S["method"] != "modified_beam_search":
        print("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.")
        S["hotwords"] = []
    if S["pre"]:
        out = []
        for y in ys:
            try:
                z = S["pre"](y)
                ok = isinstance(z, list) and len(z) == len(y) and all(math.isfinite(v) for v in z)
            except Exception:
                ok = False
            if not ok:
                skipped.add("전처리")
            out.append(z if ok else y)
        ys = out
    hyps = [listen(y, S["method"], S["hotwords"], S["hot_score"], S["paths"]) for y in ys]
    if S["post"]:
        out = []
        for h in hyps:
            try:
                z = S["post"](h)
                ok = isinstance(z, str)
            except Exception:
                ok = False
            if not ok:
                skipped.add("후처리")
            out.append(z if ok else h)
        hyps = out
    if skipped:
        print(f"[주의] {' · '.join(sorted(skipped))} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.")
    return hyps


def apply_dict(text, table):
    for wrong, right in table.items():
        text = text.replace(wrong, right)
    return text


def fuzzy_fix(text, lexicon, ratio):
    """용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다."""
    text = text.replace(" ", "")
    for word in lexicon:
        n = len(word)
        if word in text or len(text) < n:
            continue
        best = min(range(len(text) - n + 1), key=lambda s: jamo_dist(word, text[s:s + n]))
        if jamo_dist(word, text[best:best + n]) <= ratio * jamo_len(word):
            text = text[:best] + word + text[best + n:]
    return text


# ---------- 제출 · 마감 · 참가 코드 ----------
MAX_SUBMITS = 5


class Cup:
    """숨은 평가 세트와 제출 기록. 공개 순위표 점수만 바로 보여 주고, 비공개 점수는 마감 뒤에 연다."""

    def __init__(self, hidden):
        self.hidden = hidden                             # 짝수 번째 = 공개 순위표 · 홀수 번째 = 비공개
        self.subs = []
        self.closed = False

    def left(self):
        return MAX_SUBMITS - len(self.subs)

    def submit(self, system, note=""):
        if self.closed:
            return None
        hyps = run_system(system, [it["y"] for it in self.hidden])
        sig = "\n".join(hyps)
        for s in self.subs:
            if s["sig"] == sig:                          # 결과가 같으면 제출 횟수를 쓰지 않는다
                return s["public"]
        if self.left() <= 0:
            return None
        pub = grade(self.hidden[0::2], hyps[0::2])
        pri = grade(self.hidden[1::2], hyps[1::2])
        self.subs.append({"no": len(self.subs) + 1, "note": note, "public": pub["score"], "_private": pri["score"], "sig": sig})
        return pub["score"]

    def table(self):
        return [{"제출": s["no"], "설명": s["note"], "공개 점수": s["public"], **({"비공개 점수": s["_private"]} if self.closed else {})} for s in self.subs]

    def close(self, pick=None):
        """마감: 최종 제출 하나를 고르고(고르지 않으면 공개 점수가 가장 높은 것) 비공개 점수를 연다."""
        self.closed = True
        if not self.subs:
            return None
        s = next((x for x in self.subs if x["no"] == pick), None) or max(self.subs, key=lambda x: (x["public"], -x["no"]))
        return {"pick": s["no"], "public": s["public"], "private": s["_private"], "best_private": max(x["_private"] for x in self.subs), "n": len(self.subs)}


HOT = HAZARDS + ["창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"]
HID = make_items(range(20, 50))                          # 숨은 평가 세트 30개: 짝수 번째 15개 = 공개 순위표, 홀수 번째 15개 = 비공개
CUP = Cup(HID)

BEAM = {"method": "modified_beam_search", "hotwords": HOT, "hot_score": 2.0}
SYSTEMS = [("빔 + 핫워드", BEAM),
           ("+ 용어집 0.25", {**BEAM, "post": lambda h: fuzzy_fix(h, GLOSSARY, 0.25)}),
           ("+ 용어집 0.34", {**BEAM, "post": lambda h: fuzzy_fix(h, GLOSSARY, 0.34)}),
           ("+ 용어집 0.45", {**BEAM, "post": lambda h: fuzzy_fix(h, GLOSSARY, 0.45)}),
           ("+ 용어집 0.6", {**BEAM, "post": lambda h: fuzzy_fix(h, GLOSSARY, 0.6)})]
for note, system in SYSTEMS:
    CUP.submit(system, note)
print(f"제출 {len(CUP.subs)}번 · 남은 {CUP.left()}번")

# ── 마감 전: 공개 점수만 보인다 ──
before = CUP.table()
ok_hidden = len(before) == 5 and all("비공개 점수" not in r for r in before)

# ── 제출 횟수: 같은 결과는 횟수를 쓰지 않고, 여섯 번째는 거절한다 ──
again = CUP.submit(SYSTEMS[0][1], "다시 낸 첫 제출")
sixth = CUP.submit({**BEAM, "post": lambda h: fuzzy_fix(h, GLOSSARY, 0.3)}, "여섯 번째")
ok_limit = again == before[0]["공개 점수"] and len(CUP.subs) == 5 and sixth is None

# ── 마감: 비공개 점수를 연다 ──
RES = CUP.close()
after = CUP.table()
ok_open = all("비공개 점수" in r for r in after) and CUP.submit(BEAM, "마감 뒤") is None
for r in after:
    print(f"{r['제출']}번 {r['설명']} · 공개 {r['공개 점수']} → 비공개 {r['비공개 점수']} (차이 {r['비공개 점수'] - r['공개 점수']:+.1f})")
print(f"최종 제출 {RES['pick']}번째 · 공개 {RES['public']} → 비공개(최종 점수) {RES['private']} · 비공개가 가장 높았던 제출 {RES['best_private']}")
if RES["private"] < RES["best_private"]:
    print("   비공개 점수가 가장 높았던 제출은 따로 있었습니다. 공개 순위표만 보고는 알 수 없었습니다.")

# 15개짜리 세트의 점수는 같은 시스템이어도 세트마다 다르다
gaps = [abs(r["비공개 점수"] - r["공개 점수"]) for r in after]
ok_gap = len(gaps) == 5 and max(gaps) > 0 and RES["private"] <= RES["best_private"]

check(ok_hidden and ok_limit and ok_open and ok_gap and RES["public"] == max(r["공개 점수"] for r in after),
      "마감 전에는 공개 점수만 보이고, 같은 결과는 횟수를 쓰지 않고, 여섯 번째 제출은 거절되고, 마감 뒤에야 비공개 점수가 열려야 해요.")

shake.typescript:
// D48 · 공개 점수와 비공개 점수 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d48_shake.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
//   숨은 평가 세트에 제출하고 마감해 비공개 점수를 연다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

function same(a: unknown, b: unknown): boolean {
  // 값이 같은지(리스트 · 객체 포함) 비교
  return JSON.stringify(a) === JSON.stringify(b);
}

const SR = 4000; // 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
const N = 2000;
const PLACES: string[] = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"];
const HAZARDS: string[] = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"];
const GLOSSARY: string[] = [...PLACES, ...HAZARDS]; // 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
const PHRASE: Record<string, string> = {
  추락: "작업자가 추락했습니다", 화재: "화재가 발생했습니다", 누출: "가스가 누출되고 있습니다", 감전: "작업자가 감전됐습니다",
  끼였: "손이 끼였습니다", 붕괴: "벽이 붕괴됐습니다", 연기: "연기가 나고 있습니다",
};
const CONF: Record<string, string> = { // 받아쓰기가 자주 헷갈리는 모양
  추락: "주락", 화재: "화제", 누출: "노출", 감전: "반전", 끼였: "끼었", 붕괴: "봉괴", 연기: "연귀",
  "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", 옥상냉각탑: "옥상냉각답",
  "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", 정문주차장: "정문주자장", "2층용접장": "이층용접장",
};
const KINDS: string[] = ["공장", "건설", "경보"];
const SNRS: number[] = [5, 10, 15];

type Item = { id: string; k: number; text: string; kw: string[]; kind: string; snr: number; clean: number[]; y: number[] };
type System = { pre?: ((y: number[]) => any) | null; method?: string; hotwords?: string[]; hot_score?: number; paths?: number; post?: ((h: string) => any) | null };
type Row = { id: string; noise: string; snr: number; cer: number; found: number; kw: number; hyp: string };
type Grade = { score: number; cer: number; recall: number; rows: Row[] };
const BASELINE: Required<System> = { pre: null, method: "greedy_search", hotwords: [], hot_score: 2.0, paths: 4, post: null };

function rnd(a: number, b: number = 0): number {
  // 같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)
  let h = (a * 2654435761 + b * 40503 + 12345) % 4294967296;
  h = (h ^ (h >>> 15)) >>> 0;
  h = Math.imul(h, 2246822519) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  return h / 4294967296;
}

// ---------- 지표 ----------
function clean(s: string): string {
  return s.replace(/[^0-9A-Za-z가-힣]/g, "");
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다
  const r = [...clean(ref)], h = [...clean(hyp)];
  const d: number[] = Array.from({ length: h.length + 1 }, (_, i) => i);
  r.forEach((a, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    h.forEach((b, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (a !== b ? 1 : 0));
      prev = t;
    });
  });
  return d[h.length] / Math.max(1, r.length);
}

function keywordRecall(keywords: string[], hyp: string): [number, number] {
  // 안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수
  const h = hyp.replace(/\s/g, "");
  return [keywords.filter((k) => h.includes(k)).length, keywords.length];
}

function safetyScore(c: number, recall: number): number {
  // 대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다
  return roundHalfUp(100 * (0.5 * (1 - Math.min(c, 1.0)) + 0.5 * recall), 1);
}

function grade(items: Item[], hyps: string[]): Grade {
  // 발화별 채점표와 전체 점수
  const rows: Row[] = [];
  let found = 0, total = 0;
  items.forEach((it, i) => {
    const [f, n] = keywordRecall(it.kw, hyps[i]);
    found += f;
    total += n;
    rows.push({ id: it.id, noise: it.kind, snr: it.snr, cer: cer(it.text, hyps[i]), found: f, kw: n, hyp: hyps[i] });
  });
  const c = rows.reduce((s, r) => s + r.cer, 0) / rows.length;
  const rec = found / Math.max(1, total);
  return { score: safetyScore(c, rec), cer: c, recall: rec, rows };
}

// ---------- 한글 자모 거리 ----------
function jamo(s: string): string[] {
  // 한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로
  const out: string[] = [];
  for (const ch of s) {
    const o = ch.charCodeAt(0) - 0xac00;
    if (o >= 0 && o < 11172) out.push("초" + Math.floor(o / 588), "중" + Math.floor((o % 588) / 28), "종" + (o % 28));
    else out.push(ch);
  }
  return out;
}

function jamoLen(s: string): number {
  return jamo(s).length;
}

function jamoDist(a0: string, b0: string): number {
  // 두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1
  const a = jamo(a0), b = jamo(b0);
  const d: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
  a.forEach((x, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    b.forEach((y, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (x !== y ? 1 : 0));
      prev = t;
    });
  });
  return d[b.length];
}

function argmin<T>(xs: T[], key: (x: T) => number): number {
  // 가장 작은 값의 번호 (같으면 앞의 것)
  let best = 0;
  xs.forEach((x, i) => { if (key(x) < key(xs[best])) best = i; });
  return best;
}

function heardAs(keyword: string, hyp: string): string {
  // 놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것
  const t = clean(hyp), n = keyword.length;
  if (t.length < n) return t;
  const segs: string[] = [];
  for (let s = 0; s <= t.length - n; s++) segs.push(t.slice(s, s + n));
  return segs[argmin(segs, (seg) => jamoDist(keyword, seg))];
}

// ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
function toneHz(k: number): number {
  return 300 + 30 * k;
}

function makeText(k: number): [string, string[]] {
  const place = PLACES[k % 10], hazard = HAZARDS[(k * 3 + Math.floor(k / 7)) % 7];
  return [`${place}에서 ${PHRASE[hazard]}`, [place, hazard]];
}

function makeNoise(kind: string, n: number): number[] {
  const nz: number[] = [];
  for (let i = 0; i < n; i++) {
    const w = (rnd(7, i) * 2 - 1) * Math.sqrt(3); // 평균 0 · 힘 1인 잡음
    if (kind === "공장") { // 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
      let hum = 0;
      for (const [f, a, p] of [[50, 1.0, 0.3], [100, 0.7, 1.7], [150, 0.5, 4.1]]) hum += a * Math.sin((2 * Math.PI * f * i) / SR + p);
      nz.push(hum + 0.5 * w);
    } else if (kind === "건설") { // 망치 소리(짧고 센 넓은 잡음) + 엔진
      nz.push(3 * w * Math.exp(-(i % 1320) / 48) + 0.3 * w);
    } else { // 경보: 두 음을 오가는 경보음 + 배경
      nz.push(Math.sin((2 * Math.PI * (Math.floor(i / 500) % 2 === 0 ? 800 : 1100) * i) / SR) + 0.4 * w);
    }
  }
  return nz;
}

function makeItem(k: number): Item {
  // 발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean
  const [text, kw] = makeText(k);
  const kind = KINDS[k % 3], snr = SNRS[Math.floor(k / 3) % 3];
  const f = toneHz(k);
  const cleanY = Array.from({ length: N }, (_, i) => 0.5 * Math.sin((2 * Math.PI * f * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 250 * i) / SR)); // 목소리 = 높이 f + 기본음 250 Hz
  const nz = makeNoise(kind, N);
  const pS = cleanY.reduce((s, v) => s + v * v, 0) / N;
  const g = Math.sqrt(pS / (10 ** (snr / 10) * (nz.reduce((s, v) => s + v * v, 0) / N)));
  return { id: `S${String(k + 1).padStart(2, "0")}`, k, text, kw, kind, snr, clean: cleanY, y: cleanY.map((a, i) => a + g * nz[i]) };
}

function makeItems(ks: number[]): Item[] {
  return ks.map(makeItem);
}

function range(a: number, b: number): number[] {
  return Array.from({ length: b - a }, (_, i) => a + i);
}

// ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
function highpass(y: number[], cutoff: number): number[] {
  // cutoff(Hz)보다 낮은 소리를 줄인 소리
  const out = [...y];
  const w0 = (2 * Math.PI * cutoff) / SR;
  for (const q of [0.5412, 1.3066]) {
    const al = Math.sin(w0) / (2 * q);
    const a0 = 1 + al, a1 = -2 * Math.cos(w0), a2 = 1 - al;
    const b0 = (1 + Math.cos(w0)) / 2, b1 = -(1 + Math.cos(w0));
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let i = 0; i < out.length; i++) {
      const x = out[i];
      const v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0;
      x2 = x1; x1 = x; y2 = y1; y1 = v;
      out[i] = v;
    }
  }
  return out;
}

// ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
function ampAt(y: number[], hz: number): number {
  // hz 성분의 크기 (괴츨 방법)
  const c = 2 * Math.cos((2 * Math.PI * hz) / SR);
  let s1 = 0, s2 = 0;
  for (const v of y) {
    const s0 = v + c * s1 - s2;
    s2 = s1;
    s1 = s0;
  }
  return (Math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2) / y.length;
}

function listen(y: number[], method: string = "greedy_search", hotwords: string[] = [], hotScore: number = 2.0, paths: number = 4): string {
  const amps = range(0, 50).map((k) => ampAt(y, toneHz(k)));
  const k = amps.indexOf(Math.max(...amps));
  const aP = ampAt(y, 250);
  const speech = (amps[k] ** 2 + aP ** 2) / 2;
  const noise = Math.max(y.reduce((s, v) => s + v * v, 0) / y.length - speech, 1e-4);
  const clarity = (speech / noise) * Math.min(1.0, aP / amps[k] / 0.6) ** 2; // 기본음이 잘려 나가면 또렷함이 크게 준다
  let p = 1.0 / (1 + 0.08 * clarity);
  if (method === "modified_beam_search") p *= paths >= 4 ? 0.85 : 0.92; // 후보 문장을 여럿 들고 가면 덜 틀린다
  let [text, kw] = makeText(k);
  kw.forEach((w, j) => {
    const pw = hotwords.includes(w) ? p / (1 + 0.8 * hotScore) : p;
    if (rnd(k, 10 + j) < pw) text = text.replaceAll(w, CONF[w]);
  });
  text = [...text].map((ch, i) => (ch >= "가" && ch <= "힣" && rnd(k, 100 + i) < p * 0.2 ? "가" : ch)).join("");
  if (hotwords.length > 0 && rnd(k, 50) < 0.03 * hotScore ** 2) { // 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
    text = text.slice(0, text.lastIndexOf(" ")) + " " + hotwords[k % hotwords.length];
  }
  return text;
}

function runSystem(system: System | null, ys: number[][]): string[] {
  // 시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다
  const S = { ...BASELINE, ...(system ?? {}) };
  const skipped = new Set<string>();
  if (S.hotwords.length > 0 && S.method !== "modified_beam_search") {
    console.log("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.");
    S.hotwords = [];
  }
  if (S.pre) {
    ys = ys.map((y) => {
      let z: any, ok: boolean;
      try {
        z = S.pre!(y);
        ok = Array.isArray(z) && z.length === y.length && z.every((v: number) => Number.isFinite(v));
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("전처리");
      return ok ? z : y;
    });
  }
  let hyps = ys.map((y) => listen(y, S.method, S.hotwords, S.hot_score, S.paths));
  if (S.post) {
    hyps = hyps.map((h) => {
      let z: any, ok: boolean;
      try {
        z = S.post!(h);
        ok = typeof z === "string";
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("후처리");
      return ok ? z : h;
    });
  }
  if (skipped.size > 0) console.log(`[주의] ${[...skipped].sort().join(" · ")} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.`);
  return hyps;
}

function applyDict(text: string, table: Record<string, string>): string {
  for (const [wrong, right] of Object.entries(table)) text = text.replaceAll(wrong, right);
  return text;
}

function fuzzyFix(text: string, lexicon: string[], ratio: number): string {
  // 용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다
  text = text.replaceAll(" ", "");
  for (const word of lexicon) {
    const n = word.length;
    if (text.includes(word) || text.length < n) continue;
    const starts = range(0, text.length - n + 1);
    const best = starts[argmin(starts, (s) => jamoDist(word, text.slice(s, s + n)))];
    if (jamoDist(word, text.slice(best, best + n)) <= ratio * jamoLen(word)) text = text.slice(0, best) + word + text.slice(best + n);
  }
  return text;
}

// ---------- 제출 · 마감 · 참가 코드 ----------
const MAX_SUBMITS = 5;
type Sub = { no: number; note: string; public: number; _private: number; sig: string };

class Cup {
  // 숨은 평가 세트와 제출 기록. 공개 순위표 점수만 바로 보여 주고, 비공개 점수는 마감 뒤에 연다
  hidden: Item[]; // 짝수 번째 = 공개 순위표 · 홀수 번째 = 비공개
  subs: Sub[] = [];
  closed = false;

  constructor(hidden: Item[]) {
    this.hidden = hidden;
  }

  left(): number {
    return MAX_SUBMITS - this.subs.length;
  }

  submit(system: System | null, note: string = ""): number | null {
    if (this.closed) return null;
    const hyps = runSystem(system, this.hidden.map((it) => it.y));
    const sig = hyps.join("\n");
    for (const s of this.subs) if (s.sig === sig) return s.public; // 결과가 같으면 제출 횟수를 쓰지 않는다
    if (this.left() <= 0) return null;
    const pub = grade(this.hidden.filter((_, i) => i % 2 === 0), hyps.filter((_, i) => i % 2 === 0));
    const pri = grade(this.hidden.filter((_, i) => i % 2 === 1), hyps.filter((_, i) => i % 2 === 1));
    this.subs.push({ no: this.subs.length + 1, note, public: pub.score, _private: pri.score, sig });
    return pub.score;
  }

  table(): Record<string, any>[] {
    return this.subs.map((s) => ({ 제출: s.no, 설명: s.note, "공개 점수": s.public, ...(this.closed ? { "비공개 점수": s._private } : {}) }));
  }

  close(pick: number | null = null): { pick: number; public: number; private: number; best_private: number; n: number } | null {
    // 마감: 최종 제출 하나를 고르고(고르지 않으면 공개 점수가 가장 높은 것) 비공개 점수를 연다
    this.closed = true;
    if (this.subs.length === 0) return null;
    let s = this.subs.find((x) => x.no === pick);
    if (!s) s = this.subs.reduce((a, b) => (b.public > a.public ? b : a)); // 같으면 앞의 제출
    return { pick: s.no, public: s.public, private: s._private, best_private: Math.max(...this.subs.map((x) => x._private)), n: this.subs.length };
  }
}

const HOT: string[] = [...HAZARDS, "창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"];
const HID = makeItems(range(20, 50)); // 숨은 평가 세트 30개: 짝수 번째 15개 = 공개 순위표, 홀수 번째 15개 = 비공개
const CUP = new Cup(HID);

const BEAM: System = { method: "modified_beam_search", hotwords: HOT, hot_score: 2.0 };
const SYSTEMS: [string, System][] = [
  ["빔 + 핫워드", BEAM],
  ["+ 용어집 0.25", { ...BEAM, post: (h) => fuzzyFix(h, GLOSSARY, 0.25) }],
  ["+ 용어집 0.34", { ...BEAM, post: (h) => fuzzyFix(h, GLOSSARY, 0.34) }],
  ["+ 용어집 0.45", { ...BEAM, post: (h) => fuzzyFix(h, GLOSSARY, 0.45) }],
  ["+ 용어집 0.6", { ...BEAM, post: (h) => fuzzyFix(h, GLOSSARY, 0.6) }],
];
for (const [note, system] of SYSTEMS) CUP.submit(system, note);
console.log(`제출 ${CUP.subs.length}번 · 남은 ${CUP.left()}번`);

// ── 마감 전: 공개 점수만 보인다 ──
const before = CUP.table();
const okHidden = before.length === 5 && before.every((r) => !("비공개 점수" in r));

// ── 제출 횟수: 같은 결과는 횟수를 쓰지 않고, 여섯 번째는 거절한다 ──
const again = CUP.submit(SYSTEMS[0][1], "다시 낸 첫 제출");
const sixth = CUP.submit({ ...BEAM, post: (h) => fuzzyFix(h, GLOSSARY, 0.3) }, "여섯 번째");
const okLimit = again === before[0]["공개 점수"] && CUP.subs.length === 5 && sixth === null;

// ── 마감: 비공개 점수를 연다 ──
const RES = CUP.close()!;
const after = CUP.table();
const okOpen = after.every((r) => "비공개 점수" in r) && CUP.submit(BEAM, "마감 뒤") === null;
for (const r of after) {
  const diff = r["비공개 점수"] - r["공개 점수"];
  console.log(`${r["제출"]}번 ${r["설명"]} · 공개 ${r["공개 점수"]} → 비공개 ${r["비공개 점수"]} (차이 ${diff >= 0 ? "+" : "-"}${Math.abs(diff).toFixed(1)})`);
}
console.log(`최종 제출 ${RES.pick}번째 · 공개 ${RES.public} → 비공개(최종 점수) ${RES.private} · 비공개가 가장 높았던 제출 ${RES.best_private}`);
if (RES.private < RES.best_private) console.log("   비공개 점수가 가장 높았던 제출은 따로 있었습니다. 공개 순위표만 보고는 알 수 없었습니다.");

// 15개짜리 세트의 점수는 같은 시스템이어도 세트마다 다르다
const gaps = after.map((r) => Math.abs(r["비공개 점수"] - r["공개 점수"]));
const okGap = gaps.length === 5 && Math.max(...gaps) > 0 && RES.private <= RES.best_private;

check(
  okHidden && okLimit && okOpen && okGap && RES.public === Math.max(...after.map((r) => r["공개 점수"])),
  "마감 전에는 공개 점수만 보이고, 같은 결과는 횟수를 쓰지 않고, 여섯 번째 제출은 거절되고, 마감 뒤에야 비공개 점수가 열려야 해요.",
);

build.python:
# D48 · 내 시스템 조립하기 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d48_build.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
#   전처리 · 디코딩 · 후처리 칸을 채워 시스템을 만들고, 틀린 칸은 건너뛰게 한다
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import math, re
from collections import Counter


SR = 4000                                                # 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
N = 2000
PLACES = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"]
HAZARDS = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"]
GLOSSARY = PLACES + HAZARDS                              # 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
PHRASE = {"추락": "작업자가 추락했습니다", "화재": "화재가 발생했습니다", "누출": "가스가 누출되고 있습니다", "감전": "작업자가 감전됐습니다",
          "끼였": "손이 끼였습니다", "붕괴": "벽이 붕괴됐습니다", "연기": "연기가 나고 있습니다"}
CONF = {"추락": "주락", "화재": "화제", "누출": "노출", "감전": "반전", "끼였": "끼었", "붕괴": "봉괴", "연기": "연귀",          # 받아쓰기가 자주 헷갈리는 모양
        "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", "옥상냉각탑": "옥상냉각답",
        "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", "정문주차장": "정문주자장", "2층용접장": "이층용접장"}
KINDS = ["공장", "건설", "경보"]
SNRS = [5, 10, 15]
BASELINE = {"pre": None, "method": "greedy_search", "hotwords": [], "hot_score": 2.0, "paths": 4, "post": None}


def rnd(a, b=0):
    """같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)."""
    h = (a * 2654435761 + b * 40503 + 12345) & 0xFFFFFFFF
    h = (h ^ (h >> 15)) & 0xFFFFFFFF
    h = (h * 2246822519) & 0xFFFFFFFF
    h = (h ^ (h >> 13)) & 0xFFFFFFFF
    return h / 4294967296


# ---------- 지표 ----------
def clean(s):
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


def cer(ref, hyp):
    """글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다."""
    r, h = clean(ref), clean(hyp)
    d = list(range(len(h) + 1))
    for i, a in enumerate(r, 1):
        prev, d[0] = d[0], i
        for j, b in enumerate(h, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (a != b))
    return d[-1] / max(1, len(r))


def keyword_recall(keywords, hyp):
    """안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수."""
    h = re.sub(r"\s", "", hyp)
    return sum(k in h for k in keywords), len(keywords)


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def safety_score(c, recall):
    """대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다."""
    return round_half_up(100 * (0.5 * (1 - min(c, 1.0)) + 0.5 * recall), 1)


def grade(items, hyps):
    """발화별 채점표와 전체 점수."""
    rows, found, total = [], 0, 0
    for it, h in zip(items, hyps):
        f, n = keyword_recall(it["kw"], h)
        found += f
        total += n
        rows.append({"id": it["id"], "noise": it["kind"], "snr": it["snr"], "cer": cer(it["text"], h), "found": f, "kw": n, "hyp": h})
    c = sum(r["cer"] for r in rows) / len(rows)
    rec = found / max(1, total)
    return {"score": safety_score(c, rec), "cer": c, "recall": rec, "rows": rows}


# ---------- 한글 자모 거리 ----------
def jamo(s):
    """한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로."""
    out = []
    for ch in s:
        o = ord(ch) - 0xAC00
        if 0 <= o < 11172:
            out += [("초", o // 588), ("중", (o % 588) // 28), ("종", o % 28)]
        else:
            out.append(ch)
    return out


def jamo_len(s):
    return len(jamo(s))


def jamo_dist(a, b):
    """두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1."""
    a, b = jamo(a), jamo(b)
    d = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        prev, d[0] = d[0], i
        for j, y in enumerate(b, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (x != y))
    return d[-1]


def heard_as(keyword, hyp):
    """놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것."""
    t = clean(hyp)
    n = len(keyword)
    if len(t) < n:
        return t
    return min((t[s:s + n] for s in range(len(t) - n + 1)), key=lambda seg: jamo_dist(keyword, seg))


# ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
def tone_hz(k):
    return 300 + 30 * k


def make_text(k):
    place, hazard = PLACES[k % 10], HAZARDS[(k * 3 + k // 7) % 7]
    return f"{place}에서 {PHRASE[hazard]}", [place, hazard]


def make_noise(kind, n):
    nz = []
    for i in range(n):
        w = (rnd(7, i) * 2 - 1) * math.sqrt(3)           # 평균 0 · 힘 1인 잡음
        if kind == "공장":                                # 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
            hum = sum(a * math.sin(2 * math.pi * f * i / SR + p) for f, a, p in [(50, 1.0, 0.3), (100, 0.7, 1.7), (150, 0.5, 4.1)])
            nz.append(hum + 0.5 * w)
        elif kind == "건설":                              # 망치 소리(짧고 센 넓은 잡음) + 엔진
            nz.append(3 * w * math.exp(-(i % 1320) / 48) + 0.3 * w)
        else:                                            # 경보: 두 음을 오가는 경보음 + 배경
            nz.append(math.sin(2 * math.pi * (800 if (i // 500) % 2 == 0 else 1100) * i / SR) + 0.4 * w)
    return nz


def make_item(k):
    """발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean"""
    text, kw = make_text(k)
    kind, snr = KINDS[k % 3], SNRS[(k // 3) % 3]
    f = tone_hz(k)
    clean_y = [0.5 * math.sin(2 * math.pi * f * i / SR) + 0.3 * math.sin(2 * math.pi * 250 * i / SR) for i in range(N)]   # 목소리 = 높이 f + 기본음 250 Hz
    nz = make_noise(kind, N)
    p_s = sum(v * v for v in clean_y) / N
    g = math.sqrt(p_s / (10 ** (snr / 10) * sum(v * v for v in nz) / N))
    return {"id": f"S{k + 1:02d}", "k": k, "text": text, "kw": kw, "kind": kind, "snr": snr, "clean": clean_y, "y": [a + g * b for a, b in zip(clean_y, nz)]}


def make_items(ks):
    return [make_item(k) for k in ks]


# ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
def highpass(y, cutoff):
    """cutoff(Hz)보다 낮은 소리를 줄인 소리."""
    out = list(y)
    w0 = 2 * math.pi * cutoff / SR
    for q in (0.5412, 1.3066):
        al = math.sin(w0) / (2 * q)
        a0, a1, a2 = 1 + al, -2 * math.cos(w0), 1 - al
        b0 = (1 + math.cos(w0)) / 2
        b1 = -(1 + math.cos(w0))
        x1 = x2 = y1 = y2 = 0.0
        for i, x in enumerate(out):
            v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0
            x2, x1, y2, y1 = x1, x, y1, v
            out[i] = v
    return out


# ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
def amp_at(y, hz):
    """hz 성분의 크기 (괴츨 방법)"""
    c = 2 * math.cos(2 * math.pi * hz / SR)
    s1 = s2 = 0.0
    for v in y:
        s1, s2 = v + c * s1 - s2, s1
    return math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2 / len(y)


def listen(y, method="greedy_search", hotwords=(), hot_score=2.0, paths=4):
    amps = [amp_at(y, tone_hz(k)) for k in range(50)]
    k = amps.index(max(amps))
    a_p = amp_at(y, 250)
    speech = (amps[k] ** 2 + a_p ** 2) / 2
    noise = max(sum(v * v for v in y) / len(y) - speech, 1e-4)
    ratio = a_p / amps[k] if amps[k] > 0 else 0.0                       # 소리가 전부 0이면 기본음 비율은 0
    clarity = speech / noise * min(1.0, ratio / 0.6) ** 2     # 기본음이 잘려 나가면 또렷함이 크게 준다
    if not math.isfinite(clarity):
        clarity = 0.0
    p = 1.0 / (1 + 0.08 * clarity)
    if method == "modified_beam_search":
        p *= 0.85 if paths >= 4 else 0.92                 # 후보 문장을 여럿 들고 가면 덜 틀린다
    text, kw = make_text(k)
    for j, w in enumerate(kw):
        pw = p / (1 + 0.8 * hot_score) if w in hotwords else p
        if rnd(k, 10 + j) < pw:
            text = text.replace(w, CONF[w])
    text = "".join("가" if "가" <= ch <= "힣" and rnd(k, 100 + i) < p * 0.2 else ch for i, ch in enumerate(text))
    if hotwords and rnd(k, 50) < 0.03 * hot_score ** 2:  # 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
        text = text.rsplit(" ", 1)[0] + " " + hotwords[k % len(hotwords)]
    return text


def run_system(system, ys):
    """시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다."""
    S = {**BASELINE, **(system or {})}
    skipped = set()
    if S["hotwords"] and S["method"] != "modified_beam_search":
        print("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.")
        S["hotwords"] = []
    if S["pre"]:
        out = []
        for y in ys:
            try:
                z = S["pre"](y)
                ok = isinstance(z, list) and len(z) == len(y) and all(math.isfinite(v) for v in z)
            except Exception:
                ok = False
            if not ok:
                skipped.add("전처리")
            out.append(z if ok else y)
        ys = out
    hyps = [listen(y, S["method"], S["hotwords"], S["hot_score"], S["paths"]) for y in ys]
    if S["post"]:
        out = []
        for h in hyps:
            try:
                z = S["post"](h)
                ok = isinstance(z, str)
            except Exception:
                ok = False
            if not ok:
                skipped.add("후처리")
            out.append(z if ok else h)
        hyps = out
    if skipped:
        print(f"[주의] {' · '.join(sorted(skipped))} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.")
    return hyps


def apply_dict(text, table):
    for wrong, right in table.items():
        text = text.replace(wrong, right)
    return text


def fuzzy_fix(text, lexicon, ratio):
    """용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다."""
    text = text.replace(" ", "")
    for word in lexicon:
        n = len(word)
        if word in text or len(text) < n:
            continue
        best = min(range(len(text) - n + 1), key=lambda s: jamo_dist(word, text[s:s + n]))
        if jamo_dist(word, text[best:best + n]) <= ratio * jamo_len(word):
            text = text[:best] + word + text[best + n:]
    return text


HOT = HAZARDS + ["창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"]
DEV = make_items(range(20))
YS = [x["y"] for x in DEV]
LOG = []


def evaluate(system, label):
    """시스템을 공개 세트에 돌려 채점하고 실험 기록(LOG)에 남긴다. 오류가 나면 None."""
    try:
        g = grade(DEV, run_system(system, YS))
    except Exception as e:
        print(f"[{label}] 실행 중 오류 ({type(e).__name__}: {str(e)[:60]})")
        return None
    LOG.append({"실험": label, "점수": g["score"]})
    print(f"[{label}] 점수 {g['score']} · CER {g['cer'] * 100:.1f}% · 키워드 재현율 {g['recall'] * 100:.1f}%")
    return g


def practice(run, want):
    """직접 쓴 함수 채점: 아직 안 썼거나 오류가 나도 멈추지 않고 False를 돌려준다."""
    try:
        got = run()
    except Exception:
        return False
    items = got if isinstance(got, (list, tuple)) else [got]
    return all(x is not None for x in items) and list(items) == list(want if isinstance(want, (list, tuple)) else [want])


def tool(ok, mine, ref, name):
    """내 함수가 통과하면 내 것을, 아니면 주최 측 도구를 쓴다 (아래 단계가 멈추지 않게)."""
    print(f"이후 단계는 {'내가 쓴' if ok else '주최 측의'} {name}을(를) 씁니다.")
    return mine if ok else ref


def my_apply_dict(text, table):
    return None                                          # 아직 쓰지 않은 칸


# 내 함수가 틀렸거나 비어 있어도 주최 측 함수로 이어 간다
W5_OK = practice(lambda: my_apply_dict("화제", {"화제": "화재"}), "화재")
use_dict = tool(W5_OK, my_apply_dict, apply_dict, "apply_dict")
ok_tool = W5_OK is False and use_dict("화제", {"화제": "화재"}) == "화재"

# ── 내 시스템 v1: 전처리 · 디코딩 (전처리 · 후처리 칸을 바꿔 가며 올린다) ──
BASE = evaluate(None, "기준선")
MY = {"pre": lambda y: highpass(y, 150), "method": "modified_beam_search", "paths": 4, "hotwords": HOT, "hot_score": 2.0, "post": None}
R1 = evaluate(MY, "내 시스템 v1")

# ── 내 시스템 v2: v1은 그대로 두고 후처리만 더한다 ──
TABLE = {"화제": "화재", "노출": "누출"}


def my_post(text):
    return fuzzy_fix(use_dict(text, TABLE), GLOSSARY, 0.34)


MY = {**MY, "post": my_post}
R2 = evaluate(MY, "내 시스템 v2")

# ── 칸이 틀려도 시스템은 돌아간다: 길이가 틀린 전처리 · 글이 아닌 것을 돌려주는 후처리는 그 단계만 건너뛴다 ──
broken = run_system({**MY, "pre": lambda y: y[:10], "post": lambda h: 42}, YS)
skipped_same = broken == run_system({"method": "modified_beam_search", "paths": 4, "hotwords": HOT, "hot_score": 2.0}, YS)
R3 = evaluate({**MY, "post": lambda h: 1 / 0}, "후처리에서 오류가 나는 시스템")   # 오류는 건너뛰고 받아쓴 글 그대로
silent = listen([0.0] * 800)                              # 소리가 전부 0이어도 멈추지 않고 글을 돌려준다

check(ok_tool and BASE is not None and R1 is not None and R2 is not None and R1["score"] > BASE["score"] and R2["score"] > R1["score"]
      and skipped_same and isinstance(silent, str) and silent != make_text(0)[0] and R3 is not None and len(LOG) == 4,
      "내 함수가 비어 있으면 주최 측 함수로 이어 가고, 칸을 채울수록 점수가 오르며, 잘못된 칸은 그 단계만 건너뛰어야 해요.")

build.typescript:
// D48 · 내 시스템 조립하기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d48_build.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
//   전처리 · 디코딩 · 후처리 칸을 채워 시스템을 만들고, 틀린 칸은 건너뛰게 한다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

function same(a: unknown, b: unknown): boolean {
  // 값이 같은지(리스트 · 객체 포함) 비교
  return JSON.stringify(a) === JSON.stringify(b);
}

const SR = 4000; // 가상 녹음의 표본 속도 (발화 하나 = 0.5초 = 2000 표본)
const N = 2000;
const PLACES: string[] = ["3층비계", "2번창고", "지하1층기계실", "5번라인", "옥상냉각탑", "1층하역장", "4층계단", "7번탱크", "정문주차장", "2층용접장"];
const HAZARDS: string[] = ["추락", "화재", "누출", "감전", "끼였", "붕괴", "연기"];
const GLOSSARY: string[] = [...PLACES, ...HAZARDS]; // 주최 측이 준 현장 용어집 (위치 10곳 · 위험 7가지)
const PHRASE: Record<string, string> = {
  추락: "작업자가 추락했습니다", 화재: "화재가 발생했습니다", 누출: "가스가 누출되고 있습니다", 감전: "작업자가 감전됐습니다",
  끼였: "손이 끼였습니다", 붕괴: "벽이 붕괴됐습니다", 연기: "연기가 나고 있습니다",
};
const CONF: Record<string, string> = { // 받아쓰기가 자주 헷갈리는 모양
  추락: "주락", 화재: "화제", 누출: "노출", 감전: "반전", 끼였: "끼었", 붕괴: "봉괴", 연기: "연귀",
  "3층비계": "삼층비게", "2번창고": "두번창고", "지하1층기계실": "지하일층기계실", "5번라인": "법원라인", 옥상냉각탑: "옥상냉각답",
  "1층하역장": "1층하육장", "4층계단": "사층계단", "7번탱크": "칠번탱크", 정문주차장: "정문주자장", "2층용접장": "이층용접장",
};
const KINDS: string[] = ["공장", "건설", "경보"];
const SNRS: number[] = [5, 10, 15];

type Item = { id: string; k: number; text: string; kw: string[]; kind: string; snr: number; clean: number[]; y: number[] };
type System = { pre?: ((y: number[]) => any) | null; method?: string; hotwords?: string[]; hot_score?: number; paths?: number; post?: ((h: string) => any) | null };
type Row = { id: string; noise: string; snr: number; cer: number; found: number; kw: number; hyp: string };
type Grade = { score: number; cer: number; recall: number; rows: Row[] };
const BASELINE: Required<System> = { pre: null, method: "greedy_search", hotwords: [], hot_score: 2.0, paths: 4, post: null };

function rnd(a: number, b: number = 0): number {
  // 같은 (a, b)면 늘 같은 0 ~ 1 값 (Python · TS 모두 같은 정수 계산)
  let h = (a * 2654435761 + b * 40503 + 12345) % 4294967296;
  h = (h ^ (h >>> 15)) >>> 0;
  h = Math.imul(h, 2246822519) >>> 0;
  h = (h ^ (h >>> 13)) >>> 0;
  return h / 4294967296;
}

// ---------- 지표 ----------
function clean(s: string): string {
  return s.replace(/[^0-9A-Za-z가-힣]/g, "");
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율: 띄어쓰기와 문장 부호는 빼고 센다
  const r = [...clean(ref)], h = [...clean(hyp)];
  const d: number[] = Array.from({ length: h.length + 1 }, (_, i) => i);
  r.forEach((a, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    h.forEach((b, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (a !== b ? 1 : 0));
      prev = t;
    });
  });
  return d[h.length] / Math.max(1, r.length);
}

function keywordRecall(keywords: string[], hyp: string): [number, number] {
  // 안전 키워드 가운데 받아쓴 글(공백 제외)에 들어 있는 것의 수와 전체 수
  const h = hyp.replace(/\s/g, "");
  return [keywords.filter((k) => h.includes(k)).length, keywords.length];
}

function safetyScore(c: number, recall: number): number {
  // 대회 점수(0 ~ 100): 글자 정확도 절반 + 키워드 재현율 절반. cer가 1을 넘으면 1로 본다
  return roundHalfUp(100 * (0.5 * (1 - Math.min(c, 1.0)) + 0.5 * recall), 1);
}

function grade(items: Item[], hyps: string[]): Grade {
  // 발화별 채점표와 전체 점수
  const rows: Row[] = [];
  let found = 0, total = 0;
  items.forEach((it, i) => {
    const [f, n] = keywordRecall(it.kw, hyps[i]);
    found += f;
    total += n;
    rows.push({ id: it.id, noise: it.kind, snr: it.snr, cer: cer(it.text, hyps[i]), found: f, kw: n, hyp: hyps[i] });
  });
  const c = rows.reduce((s, r) => s + r.cer, 0) / rows.length;
  const rec = found / Math.max(1, total);
  return { score: safetyScore(c, rec), cer: c, recall: rec, rows };
}

// ---------- 한글 자모 거리 ----------
function jamo(s: string): string[] {
  // 한글 음절을 초성 · 중성 · 종성으로 푼다. 그 밖의 글자는 그대로
  const out: string[] = [];
  for (const ch of s) {
    const o = ch.charCodeAt(0) - 0xac00;
    if (o >= 0 && o < 11172) out.push("초" + Math.floor(o / 588), "중" + Math.floor((o % 588) / 28), "종" + (o % 28));
    else out.push(ch);
  }
  return out;
}

function jamoLen(s: string): number {
  return jamo(s).length;
}

function jamoDist(a0: string, b0: string): number {
  // 두 글을 자모로 풀어 잰 편집 거리. '화재'와 '화제'는 1
  const a = jamo(a0), b = jamo(b0);
  const d: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
  a.forEach((x, i0) => {
    let prev = d[0];
    d[0] = i0 + 1;
    b.forEach((y, j0) => {
      const t = d[j0 + 1];
      d[j0 + 1] = Math.min(d[j0 + 1] + 1, d[j0] + 1, prev + (x !== y ? 1 : 0));
      prev = t;
    });
  });
  return d[b.length];
}

function argmin<T>(xs: T[], key: (x: T) => number): number {
  // 가장 작은 값의 번호 (같으면 앞의 것)
  let best = 0;
  xs.forEach((x, i) => { if (key(x) < key(xs[best])) best = i; });
  return best;
}

function heardAs(keyword: string, hyp: string): string {
  // 놓친 키워드가 받아쓴 글에서 무엇으로 들렸는지: 길이가 같은 조각 가운데 자모 거리가 가장 가까운 것
  const t = clean(hyp), n = keyword.length;
  if (t.length < n) return t;
  const segs: string[] = [];
  for (let s = 0; s <= t.length - n; s++) segs.push(t.slice(s, s + n));
  return segs[argmin(segs, (seg) => jamoDist(keyword, seg))];
}

// ---------- 가상 녹음: 발화 번호 k = 목소리 높이(주파수), 소음은 종류와 세기(SNR)대로 섞는다 ----------
function toneHz(k: number): number {
  return 300 + 30 * k;
}

function makeText(k: number): [string, string[]] {
  const place = PLACES[k % 10], hazard = HAZARDS[(k * 3 + Math.floor(k / 7)) % 7];
  return [`${place}에서 ${PHRASE[hazard]}`, [place, hazard]];
}

function makeNoise(kind: string, n: number): number[] {
  const nz: number[] = [];
  for (let i = 0; i < n; i++) {
    const w = (rnd(7, i) * 2 - 1) * Math.sqrt(3); // 평균 0 · 힘 1인 잡음
    if (kind === "공장") { // 낮은 웅웅거림(50 · 100 · 150 Hz) + 넓은 잡음
      let hum = 0;
      for (const [f, a, p] of [[50, 1.0, 0.3], [100, 0.7, 1.7], [150, 0.5, 4.1]]) hum += a * Math.sin((2 * Math.PI * f * i) / SR + p);
      nz.push(hum + 0.5 * w);
    } else if (kind === "건설") { // 망치 소리(짧고 센 넓은 잡음) + 엔진
      nz.push(3 * w * Math.exp(-(i % 1320) / 48) + 0.3 * w);
    } else { // 경보: 두 음을 오가는 경보음 + 배경
      nz.push(Math.sin((2 * Math.PI * (Math.floor(i / 500) % 2 === 0 ? 800 : 1100) * i) / SR) + 0.4 * w);
    }
  }
  return nz;
}

function makeItem(k: number): Item {
  // 발화 하나: 정답 글 · 키워드 · 소음 종류 · 세기 · 소음이 섞인 소리 y · 깨끗한 소리 clean
  const [text, kw] = makeText(k);
  const kind = KINDS[k % 3], snr = SNRS[Math.floor(k / 3) % 3];
  const f = toneHz(k);
  const cleanY = Array.from({ length: N }, (_, i) => 0.5 * Math.sin((2 * Math.PI * f * i) / SR) + 0.3 * Math.sin((2 * Math.PI * 250 * i) / SR)); // 목소리 = 높이 f + 기본음 250 Hz
  const nz = makeNoise(kind, N);
  const pS = cleanY.reduce((s, v) => s + v * v, 0) / N;
  const g = Math.sqrt(pS / (10 ** (snr / 10) * (nz.reduce((s, v) => s + v * v, 0) / N)));
  return { id: `S${String(k + 1).padStart(2, "0")}`, k, text, kw, kind, snr, clean: cleanY, y: cleanY.map((a, i) => a + g * nz[i]) };
}

function makeItems(ks: number[]): Item[] {
  return ks.map(makeItem);
}

function range(a: number, b: number): number[] {
  return Array.from({ length: b - a }, (_, i) => a + i);
}

// ---------- 전처리: 4차 버터워스 고역 통과 필터 (2단) ----------
function highpass(y: number[], cutoff: number): number[] {
  // cutoff(Hz)보다 낮은 소리를 줄인 소리
  const out = [...y];
  const w0 = (2 * Math.PI * cutoff) / SR;
  for (const q of [0.5412, 1.3066]) {
    const al = Math.sin(w0) / (2 * q);
    const a0 = 1 + al, a1 = -2 * Math.cos(w0), a2 = 1 - al;
    const b0 = (1 + Math.cos(w0)) / 2, b1 = -(1 + Math.cos(w0));
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let i = 0; i < out.length; i++) {
      const x = out[i];
      const v = (b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2) / a0;
      x2 = x1; x1 = x; y2 = y1; y1 = v;
      out[i] = v;
    }
  }
  return out;
}

// ---------- 받아쓰기 흉내: 소리에서 몇 번째 발화인지와 또렷함을 재고, 또렷하지 않을수록 틀린다 ----------
function ampAt(y: number[], hz: number): number {
  // hz 성분의 크기 (괴츨 방법)
  const c = 2 * Math.cos((2 * Math.PI * hz) / SR);
  let s1 = 0, s2 = 0;
  for (const v of y) {
    const s0 = v + c * s1 - s2;
    s2 = s1;
    s1 = s0;
  }
  return (Math.sqrt(s1 * s1 + s2 * s2 - c * s1 * s2) * 2) / y.length;
}

function listen(y: number[], method: string = "greedy_search", hotwords: string[] = [], hotScore: number = 2.0, paths: number = 4): string {
  const amps = range(0, 50).map((k) => ampAt(y, toneHz(k)));
  const k = amps.indexOf(Math.max(...amps));
  const aP = ampAt(y, 250);
  const speech = (amps[k] ** 2 + aP ** 2) / 2;
  const noise = Math.max(y.reduce((s, v) => s + v * v, 0) / y.length - speech, 1e-4);
  const ratio = amps[k] > 0 ? aP / amps[k] : 0.0; // 소리가 전부 0이면 기본음 비율은 0
  const clarity = (speech / noise) * Math.min(1.0, ratio / 0.6) ** 2; // 기본음이 잘려 나가면 또렷함이 크게 준다
  const clear = Number.isFinite(clarity) ? clarity : 0.0;
  let p = 1.0 / (1 + 0.08 * clear);
  if (method === "modified_beam_search") p *= paths >= 4 ? 0.85 : 0.92; // 후보 문장을 여럿 들고 가면 덜 틀린다
  let [text, kw] = makeText(k);
  kw.forEach((w, j) => {
    const pw = hotwords.includes(w) ? p / (1 + 0.8 * hotScore) : p;
    if (rnd(k, 10 + j) < pw) text = text.replaceAll(w, CONF[w]);
  });
  text = [...text].map((ch, i) => (ch >= "가" && ch <= "힣" && rnd(k, 100 + i) < p * 0.2 ? "가" : ch)).join("");
  if (hotwords.length > 0 && rnd(k, 50) < 0.03 * hotScore ** 2) { // 가산 점수가 너무 크면 핫워드가 엉뚱한 곳에 끼어든다
    text = text.slice(0, text.lastIndexOf(" ")) + " " + hotwords[k % hotwords.length];
  }
  return text;
}

function runSystem(system: System | null, ys: number[][]): string[] {
  // 시스템(전처리 → 받아쓰기 → 후처리)으로 소리들을 글로 바꾼다. 내 함수가 틀린 것을 돌려주면 그 단계는 건너뛴다
  const S = { ...BASELINE, ...(system ?? {}) };
  const skipped = new Set<string>();
  if (S.hotwords.length > 0 && S.method !== "modified_beam_search") {
    console.log("[주의] 핫워드는 method가 'modified_beam_search'일 때만 듣습니다. 핫워드 없이 받아씁니다.");
    S.hotwords = [];
  }
  if (S.pre) {
    ys = ys.map((y) => {
      let z: any, ok: boolean;
      try {
        z = S.pre!(y);
        ok = Array.isArray(z) && z.length === y.length && z.every((v: number) => Number.isFinite(v));
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("전처리");
      return ok ? z : y;
    });
  }
  let hyps = ys.map((y) => listen(y, S.method, S.hotwords, S.hot_score, S.paths));
  if (S.post) {
    hyps = hyps.map((h) => {
      let z: any, ok: boolean;
      try {
        z = S.post!(h);
        ok = typeof z === "string";
      } catch {
        ok = false;
      }
      if (!ok) skipped.add("후처리");
      return ok ? z : h;
    });
  }
  if (skipped.size > 0) console.log(`[주의] ${[...skipped].sort().join(" · ")} 함수가 올바른 값을 돌려주지 않아 그 단계를 건너뛰었습니다.`);
  return hyps;
}

function applyDict(text: string, table: Record<string, string>): string {
  for (const [wrong, right] of Object.entries(table)) text = text.replaceAll(wrong, right);
  return text;
}

function fuzzyFix(text: string, lexicon: string[], ratio: number): string {
  // 용어집 맞추기: 글(공백 제외)에서 용어와 길이가 같은 조각 중 자모 거리가 가장 가까운 조각을, 거리가 ratio × 용어의 자모 수 이하이면 용어로 바꾼다
  text = text.replaceAll(" ", "");
  for (const word of lexicon) {
    const n = word.length;
    if (text.includes(word) || text.length < n) continue;
    const starts = range(0, text.length - n + 1);
    const best = starts[argmin(starts, (s) => jamoDist(word, text.slice(s, s + n)))];
    if (jamoDist(word, text.slice(best, best + n)) <= ratio * jamoLen(word)) text = text.slice(0, best) + word + text.slice(best + n);
  }
  return text;
}

const HOT: string[] = [...HAZARDS, "창고", "하역장", "주차장", "용접장", "냉각탑", "기계실", "비계", "계단", "탱크", "라인"];
const DEV = makeItems(range(0, 20));
const YS = DEV.map((x) => x.y);
const LOG: { 실험: string; 점수: number }[] = [];

function evaluate(system: System | null, label: string): Grade | null {
  // 시스템을 공개 세트에 돌려 채점하고 실험 기록(LOG)에 남긴다. 오류가 나면 null
  let g: Grade;
  try {
    g = grade(DEV, runSystem(system, YS));
  } catch (e) {
    console.log(`[${label}] 실행 중 오류 (${(e as Error).name}: ${String((e as Error).message).slice(0, 60)})`);
    return null;
  }
  LOG.push({ 실험: label, 점수: g.score });
  console.log(`[${label}] 점수 ${g.score} · CER ${(g.cer * 100).toFixed(1)}% · 키워드 재현율 ${(g.recall * 100).toFixed(1)}%`);
  return g;
}

function practice(run: () => unknown, want: unknown): boolean {
  // 직접 쓴 함수 채점: 아직 안 썼거나 오류가 나도 멈추지 않고 false를 돌려준다
  let got: unknown;
  try {
    got = run();
  } catch {
    return false;
  }
  const items = Array.isArray(got) ? got : [got];
  return items.every((x) => x !== null && x !== undefined) && same(items, Array.isArray(want) ? want : [want]);
}

function tool<F>(ok: boolean, mine: F, ref: F, name: string): F {
  // 내 함수가 통과하면 내 것을, 아니면 주최 측 도구를 쓴다 (아래 단계가 멈추지 않게)
  console.log(`이후 단계는 ${ok ? "내가 쓴" : "주최 측의"} ${name}을(를) 씁니다.`);
  return ok ? mine : ref;
}

function myApplyDict(text: string, table: Record<string, string>): string | null {
  return null; // 아직 쓰지 않은 칸
}

// 내 함수가 틀렸거나 비어 있어도 주최 측 함수로 이어 간다
const W5_OK = practice(() => myApplyDict("화제", { 화제: "화재" }), "화재");
const useDict = tool<(t: string, tb: Record<string, string>) => string | null>(W5_OK, myApplyDict, applyDict, "applyDict");
const okTool = W5_OK === false && useDict("화제", { 화제: "화재" }) === "화재";

// ── 내 시스템 v1: 전처리 · 디코딩 (전처리 · 후처리 칸을 바꿔 가며 올린다) ──
const BASE = evaluate(null, "기준선");
let MY: System = { pre: (y) => highpass(y, 150), method: "modified_beam_search", paths: 4, hotwords: HOT, hot_score: 2.0, post: null };
const R1 = evaluate(MY, "내 시스템 v1");

// ── 내 시스템 v2: v1은 그대로 두고 후처리만 더한다 ──
const TABLE: Record<string, string> = { 화제: "화재", 노출: "누출" };

function myPost(text: string): string {
  return fuzzyFix(useDict(text, TABLE) as string, GLOSSARY, 0.34);
}

MY = { ...MY, post: myPost };
const R2 = evaluate(MY, "내 시스템 v2");

// ── 칸이 틀려도 시스템은 돌아간다: 길이가 틀린 전처리 · 글이 아닌 것을 돌려주는 후처리는 그 단계만 건너뛴다 ──
const broken = runSystem({ ...MY, pre: (y) => y.slice(0, 10), post: () => 42 }, YS);
const skippedSame = same(broken, runSystem({ method: "modified_beam_search", paths: 4, hotwords: HOT, hot_score: 2.0 }, YS));
const R3 = evaluate({ ...MY, post: () => { throw new Error("division by zero"); } }, "후처리에서 오류가 나는 시스템"); // 오류는 건너뛰고 받아쓴 글 그대로
const silent = listen(new Array(800).fill(0)); // 소리가 전부 0이어도 멈추지 않고 글을 돌려준다

check(
  okTool && BASE !== null && R1 !== null && R2 !== null && R1.score > BASE.score && R2.score > R1.score &&
    skippedSame && typeof silent === "string" && silent !== makeText(0)[0] && R3 !== null && LOG.length === 4,
  "내 함수가 비어 있으면 주최 측 함수로 이어 가고, 칸을 채울수록 점수가 오르며, 잘못된 칸은 그 단계만 건너뛰어야 해요.",
);

recap.python:
# D48 · 정리 퀴즈 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d48_recap.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 모델은 쓰지 않고 가상 녹음과 규칙으로 흉내)
#   대회를 시작해 마감하기까지 만나는 여섯 상황을 계산으로 확인한다
