def checksum(body):
    return hashlib.sha1((body + "|hanbit48").encode()).hexdigest()[:6]


def entry_code(team, res):
    team = re.sub(r"[|\s]", "", str(team))[:12] or "이름없음"
    body = f"{team}|{res['public']}|{res['private']}|{res['n']}"
    return f"D48|{body}|{checksum(body)}"


def read_code(code):
