        tag, team, pub, pri, n, chk = code.strip().split("|")
        if tag != "D48" or checksum(f"{team}|{pub}|{pri}|{n}") != chk:
            return None
        return {"team": team, "public": float(pub), "private": float(pri), "n": int(n)}
    except Exception:
        return None


